"""A pulse at the start of a document, modulated by the opening token.

Message markers, formatting openers, numbers, and capitalized prose have
larger pulses than ordinary space-prefixed words. Identical initial tokens
keep the pulse; other subsequent tokens receive only a tiny background.
These broad classes approximate, rather than memorize, lexical variation.
"""
import regex
from wordfreq import zipf_frequency

READS = ()

DETERMINERS = {
    'An', 'The', 'This', 'That', 'These', 'Those', 'Some', 'Any',
    'Each', 'Every', 'All', 'No', 'Another',
}
QUESTION_WORDS = {'How', 'When', 'Where', 'Why', 'Who', 'What',
                  'Which', 'Whose'}


def opening_value(text):
    if text == '<|im_start|>':
        return 5.54
    if text == '<|im_end|>':
        return 10.61
    if text == '<|endoftext|>':
        return 2.92
    if text == ' ':
        return 1.17
    if text == '\t':
        return -1.56
    if not text.strip():
        return 0.29
    word = text.strip()
    spaced = text[0].isspace()
    if word.isdecimal():
        return 0.16 if set(word) == {'0'} else 2.77
    if word.startswith(('/*', '"""', "'''")):
        return 7.3
    if word.startswith('#') and any(c.isalpha() for c in word):
        return 0.23  # preprocessor directives, not a heading marker
    if not any(c.isalnum() for c in word):
        if word[0] == '.' and '\n' in text:
            return 2.88
        if word[0] in '([{':
            if spaced:
                return 2.09
            return 7.6 if len(word) == 1 else 2.5
        if word[0] in '#*|$':
            if word[0] == '#':
                return 3.09 if spaced else 4.55
            if word[0] == '*':
                return 3.65 if spaced else 6.67
            return 5.6
        if word[0] in "\"'":
            if spaced:
                return 2.99
            if len(word) == 1:
                return 7.92 if word == '"' else 4.98
            return 2.5
        if word[0] in '+-=<>':
            return 2.16
        if word[0] in '.,;:!?)]}':
            return 0.33
        return 3.36
    if not spaced and word in {'package', 'import', 'from', 'using'}:
        return 3.0
    if not spaced and word in {'var', 'const', 'let'}:
        return -2.1
    if regex.fullmatch('[A-Za-z]+', word):
        if spaced:
            return -0.23
        if len(word) == 1 and word.isupper():
            return -0.1
        if word in DETERMINERS:
            return 3.6
        if word in QUESTION_WORDS:
            return 1.0
        frequency = zipf_frequency(word, 'en')
        if word[0].isupper():
            return 2.83 if frequency >= 5 else 2.2
        return 0.95 if frequency >= 4 else 0.0
    for script, value in (('Han', 2.62), ('Katakana', 2.82),
                          ('Hiragana', 2.82), ('Arabic', 3.25),
                          ('Cyrillic', 1.42)):
        if regex.search(r'\p{Script=' + script + '}', word):
            return value
    return 0.77 if '\ufffd' in word else 1.18


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    fresh = carry is None or carry[0] != doc
    uniform = fresh or (carry[2] and carry[1] == token)
    value = opening_value(prefix.token_strings[-1]) if uniform else 0.003
    return (doc, token, uniform), value

"""Recognize endings of compact mathematical expressions.

Closing norm bars are strongest; brackets, squares, cubes, and LaTeX's
right command are weaker negative cases. Exponents zero and one are
positive. Prose is near zero; spaced non-formula bars are slightly positive.
The context is the last 512 characters of the current document.
"""
import re
import unicodedata

READS = ()
SIGNS = '+-*/^=−'
ANGLE_ENDS = ('⟩', '〉', '⟫')


def body_before(tail, close):
    """Contents of the most recent unmatched opening delimiter."""
    opening = {')': '(', ']': '[', '}': '{', '|': '|'}[close]
    depth = 0
    for i in range(len(tail) - 1, -1, -1):
        c = tail[i]
        if close != '|' and c == close:
            depth += 1
        elif c == opening:
            if depth == 0:
                return tail[i + 1:], tail[:i], True
            depth -= 1
    return tail[-32:], '', False


def compact(body):
    # LaTeX names stand for individual mathematical symbols, not prose.
    clean = re.sub(r'\\[A-Za-z]+', 'v', body)
    clean = unicodedata.normalize('NFKC', clean)
    if re.search(r'[A-Za-z]{3,}', clean):
        return False
    return clean.isascii() or not any(c.isalpha() and not any(k in unicodedata.name(c, '')
                   for k in ('LATIN', 'GREEK', 'MATHEMATICAL')) for c in clean)


def predict(s, prev, tail):
    q = s.strip()
    if q in ANGLE_ENDS or (q == '>' and tail.endswith('\\right')):
        return -4.4
    if q == 'right' and tail.endswith('\\'):
        return -3.35
    if q in ('rangle', 'rfloor', 'rceil') and tail.endswith('\\'):
        return -4.4
    if q and all(c in '⁰¹²³⁴⁵⁶⁷⁸⁹' for c in q):
        operators = sum(c in SIGNS for c in tail[-128:])
        n = unicodedata.numeric(q[0])
        if n == 2:
            return -1.4 if prev.strip().isdigit() else -2.25 if operators else -1.8
        return -1.35 if n == 3 else -0.5
    if q in ('^', '^{'):
        return -0.6
    if q.isdecimal() and tail.endswith('**'):
        return -2.5 if int(q) == 2 else -1.3 if int(q) == 3 else -0.3
    if q.isdecimal() and tail.endswith(('^', '^{')):
        n = int(q)
        if n == 2:
            return -1.5
        if n == 3:
            return -0.9
        return 0.9 if n == 0 else 0.2 if n == 1 else -0.3

    # Bars can be tokenized together with a bracket, exponent, or operator.
    bars = '|' in q and not any(c.isalnum() for c in q)
    bars = bars or (q in ('Vert', 'vert') and tail.endswith('\\'))
    if not bars and (not q or q[0] not in ')]}'):
        return 0.0
    recent = tail[-128:]
    variables = len(re.findall(r'(?<![A-Za-z])[A-Za-z](?![A-Za-z])', recent))
    if bars:
        left = re.sub(r'\\(?:Vert|vert)', '|', tail).rstrip('\\')
        body, before, opened = body_before(left, '|')
        operand = bool(left) and (left[-1].isalnum() or left[-1] in ')]}')
        if '|' in q and q.index('|') > 0:
            operand = q[q.index('|') - 1] in ')]}'
        operand = operand or left.endswith('\\right')
        letters = any(c.isalpha() for c in body)
        arithmetic = (any(c in '+*/^' for c in body)
                      or bool(re.search(r'\d\s*[-−]\s*\d', body)))
        formula = letters or arithmetic
        closing = (opened and operand and compact(body)
                   and '\n' not in body and len(body) < 100 and formula)
        line = left.rsplit('\n', 1)[-1]
        table = line.startswith('|') and '||' in line and '\\' not in line
        table = table and bool(re.search(r'[A-Za-z]{3,}', line))
        if closing and not table:
            if '\\langle' in body or '⟨' in body:
                return -2.0
            if re.search(r' {3,}', body):
                return -1.5
            if any(c in s for c in '.\n\r,;'):
                return -3.5
            return -3.8 if '=' in q else -7.4
        return 0.35 if s.startswith(' ') else 0.05

    body, before, opened = body_before(tail, q[0])
    simple = compact(body)
    match = re.search(r'([^\W\d_]+)(?:[ _]*\d+)?[ \t]*$', before)
    name = match[1] if match else ''
    math_function = (len(name) == 1
                     or (match and before[:match.start()].endswith('\\')))
    math_function = math_function or name in (
        'sin', 'cos', 'tan', 'sec', 'csc', 'cot', 'ln', 'log',
        'exp', 'sinh', 'cosh', 'tanh', 'arctan', 'arcsin', 'arccos',
        'max', 'min', 'diam')
    suffix = q.lstrip(')]}')
    prose_end = any(c in s for c in '\n\r.,;')
    spaced = s[:1].isspace()
    if q[0] == ')':
        if prose_end:
            if spaced and simple and variables > 4:
                return -0.65
            return -0.08 if simple else 0.02
        if '^' in suffix:
            return -2.8
        if '/' in suffix:
            return -1.2
        if '$' in suffix:
            return -1.45
        if '\\' in suffix:
            return -0.2
        if suffix:
            return -0.5 if suffix in ('=', '+', '-') else -0.1
        if prev == 'right' and tail.endswith('\\right'):
            return -3.2
        if simple:
            if math_function and any(c.isalpha() for c in body):
                return -3.0
            if variables > 3:
                return -2.3 if math_function else -1.5
            if any(c in SIGNS for c in body):
                return -1.3
            return -1.3 if math_function or spaced else -0.2
        return -0.5 if variables > 5 else 0.03
    if q[0] == ']':
        if not prose_end and math_function and simple:
            return -1.5
        if prose_end:
            return 0.03
        if variables > 4:
            return -1.1 if not suffix else -0.3
        return -1.5 if spaced else -0.25 if not body.strip().isdigit() else 0.0
    if not simple:
        return -0.2 if recent.count('$') > 1 else 0.02
    if prose_end:
        return -0.45 if recent.count('\\') > 3 else 0.02
    if not suffix:
        return -1.4
    if '\\' in suffix or '$' in suffix:
        return -1.8 if spaced else -0.75
    return -0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, prev = '', ''
    else:
        _, tail, prev = carry
    s = prefix.token_strings[-1]
    if '\ufffd' in s:
        joined = b''.join(b for b, d in zip(
            prefix.token_bytes[-3:], prefix.document_ids[-3:]) if d == doc)
        for close in ANGLE_ENDS:
            if joined.endswith(close.encode('utf-8')):
                s = close
                break
    value = predict(s, prev, tail)
    return (doc, (tail + s)[-512:], s), float(value)

"""Mostly a path-opening slash signal, with a few separate spelling responses.

A slash opening an absolute path is stronger than an interior separator or
arithmetic division. Quotes, opening brackets, assignments, directory labels,
and shell commands help identify these openings. Recent text is kept only to
recognize this syntax, and is reset at each document boundary.

There is also a secondary response to 州 (state), 洲 (continent), 舟 (boat),
romanized zhou, and Korean 주 (ju), but not every homophone. Doubled middle dots
also receive a pulse. Extra rules cover code-host domains, C++ std::, and a
negative pulse on document-initial Title:.
"""
import re

READS = ()


def response(token, history):
    s = token.strip()
    if '/' not in token:
        if token == '州':
            return 9.3
        if token.endswith('州'):
            return 4.0
        if token == '洲':
            return 5.4
        if token == '舟':
            return 4.6
        if s == '주':
            return 2.9
        if s.lower() == 'zhou':
            return 4.0 if token[0].isspace() else 6.5
        if token.lower() in ('hou', 'ou'):
            if (history[-2:] + token).lower().endswith('zhou'):
                return 10.0
        if token == '··':
            return 1.32
        if token == 'usr' and history.endswith('/'):
            return 5.5
        if token == 'root' and history.endswith('/'):
            return 0.8
        if token == '.com' and history.lower().endswith(('github', 'gitlab')):
            return 2.8
        if token == '.org' and history.lower().endswith('bitbucket'):
            return 1.6
        if token == '::' and history.endswith('std'):
            return 1.5
        if token == ':' and history == 'Title':
            return -8.2
        return 0.0

    s = token.lstrip()  # A trailing newline ends the slash syntax.
    if token == ' /':
        end = history.lower().rstrip()
        if re.search(r'(?:directory|rootdir|cwd):$', end):
            return 7.8
        if re.search(r'(?:interpreter|executable):$', end):
            return 6.0
        if re.search(r'\bfind$', end):
            return 7.0
        if re.search(r'\b(?:cd|ls|cat|rm|cp|mv|mkdir|chmod)$', end):
            return 5.1
        if re.search(r'\b(?:python\d?|bash|sh|node|ruby|perl)$', end):
            return 3.5
        if re.search(r'[=>:]$', end):
            return 4.7
        if re.search(r'\b(?:path|paths|directory|file|folder|snippet)\b', end[-100:]):
            return 4.3
        if re.search(r'(?:tool_call|execute_bash|"command"|"path")', history[-250:]):
            return 4.1
        return 1.3

    if token == '/':
        if history.endswith(('](', '#')):
            return 9.5  # Markdown link or hash-route opening.
        if history.endswith('`'):
            line = history.rsplit('\n', 1)[-1]
            return 5.8 if line.count('`') % 2 else 0.25
        if history.endswith(('"', "'", '“')):
            return 5.8
        if history.endswith(('/workspace', '/testbed')):
            return 2.1
        if not history or history.endswith('\n'):
            return 1.5
        return 0.25
    if s == '/usr':
        return 5.4
    if s == '://':
        return 1.38
    if s == ':///':
        return 5.6
    if './' in s:
        return 0.25 if '../' in s else 1.17
    if '<' in s and s.endswith('/'):
        if '"' in s or "'" in s:
            return 2.0
        return -0.35 if token[0].isspace() else 0.4
    if s.endswith('/') and s.count('/') == 1:
        head = s[:-1]
        if head == '=':
            return 10.4
        if head == ':':
            return 9.0
        if head.startswith('=') and ('"' in head or "'" in head):
            return 6.3
        if head.endswith(('"', "'")):
            if head == "'" and not token[0].isspace():
                return 2.2
            return 7.4 if token[0].isspace() else 5.9
        if head == '(':
            return 5.7 if token[0].isspace() else 3.7
        if head == '!':
            return 7.5 if history.endswith('#') else 3.5
        return {
            '[': 6.7, '{': 6.5, '>': 4.6, '`': 4.2,
            '+': 3.5, '-': 3.5, '__': 1.55,
            ')': 0.6, ']': 1.5, '}': 1.2, '$': 1.5, '*': 0.9,
        }.get(head, 0.08)
    if s.startswith((')/', '}/', ']/', '/(')):
        return 0.55
    return 0.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, history)
    return (doc, (history + token)[-400:]), value

"""A sparse lexical/formatting approximation of an early MLP component.

The strongest negative numerical motif is the second digit of 30 or 31,
particularly in dates and times. Other rules cover short/shortly/kurz,
public class declarations, joining-date labels and literal-string openers.
A z completing the spelling 'urz' also gets a negative response.
Cold starts (row/document beginnings) have a generally negative baseline.
Most other tokens get zero; diffuse lexical variation is left unmodeled.
Only a bounded text tail is retained, reset for each document.
"""
import re
import unicodedata

READS = ()
MONTH = re.compile(
    r'(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|'
    r'Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|'
    r'Dec(?:ember)?)\.?\s+3$', re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if first:
        value = -0.27
        if token == 'using':
            value = -2.15
        elif token == 'package':
            value = -1.09
        elif token == '//\n':
            value = -3.75
        elif token.startswith('/*'):
            value = -1.1
        elif token == '#include':
            value = -0.87
        elif token == '<|im_start|>':
            value = -0.05
        elif token == 'int':
            value = 2.0
        elif token == 'Title':
            value = -1.5
    elif (word == 'class' and
          re.search(r'\bpublic(?:\s+(?:abstract|final))?\s*$', tail)):
        value = 0.74
    elif token == ':' and re.search(r'\bJoined$', tail):
        value = 0.91
    elif token == ':' and tail == 'Title':
        value = 3.43
    elif '\n' in token and re.search(r'<{2,3}\s*[\'\"]?EOF$', tail):
        value = 1.0 if re.search(r'<<\s*EOF$', tail) else 0.25
    elif word == 'EOF' and re.search(r'<{2,3}\s*[\'\"]?$', tail):
        value = 1.3
    elif word in {'#', '#"'} and re.search(r'\br$', tail):
        value = 1.7 if word == '#"' else 0.8
    elif token == '0' and re.search(r'\[0{1,2}$', tail):
        value = -0.40
    else:
        # Normalize fullwidth digits, but leave other spelling intact.
        digit = unicodedata.normalize('NFKC', token)
        end = unicodedata.normalize('NFKC', tail[-60:])
        if digit in {'0', '1'} and end.endswith('3'):
            value = -0.21
            if len(end) < 2 or not end[-2].isdigit():
                value = -0.58
                if MONTH.search(end) or re.search(r'[:月]3$', end):
                    value = -1.10
    if word.lower() == 'shortly':
        value = -0.98
    elif word.lower() == 'short':
        value = -0.18
    elif word.lower() == 'thirty':
        value = -0.45
    elif word.lower() == 'kurz':
        value = -1.62
    elif word == 'z' and tail.lower().endswith('ur'):
        value = -1.6
    elif word == 'ly' and re.search(r'\bShort$', tail):
        value = -1.5
    return (doc, (tail + token)[-160:]), value

"""Detect matter-like spellings and noun+'of' constructions.

'Matter' is strongest after 'a', and persists on the following 'of'.
Question/issue/manner have a weaker related response on 'of'. Mary-name
endings and matter's Romance cognates also respond, especially when split
between tokens. Maths and repeated middle dots give negative responses.
Non-ASCII spellings are transliterated by a character table. Other
positions are zero; state is just the latest 400 bytes of this document.
The amplitudes approximate training activations, not a semantic classifier.
"""
import re
from anyascii import anyascii

READS = ()
# (ordinary context, indefinite-article context): the question / a question.
OF_NOUNS = {'question': (2.8, 6.0), 'questions': (2.3, 2.3),
            'issue': (0.8, 3.8), 'issues': (0.7, 0.7),
            'manner': (2.2, 5.5), 'problem': (0.45, 1.85)}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = carry[1] if carry is not None and carry[0] == doc else b''
    tail = raw.decode('utf-8', errors='replace')
    token = prefix.token_strings[-1]
    raw = (raw + prefix.token_bytes[-1])[-400:]
    text = raw.decode('utf-8', errors='replace')
    low = text.lower()
    match = re.search(r'[^\W\d_]+\Z', low)
    word = match.group() if match else ''
    if not word.isascii():
        word = anyascii(word).lower()
    before = low[:match.start()].rstrip() if match else ''
    previous = re.search(r"[^\W\d_]+(?:['’][^\W\d_]+)?\Z", before)
    previous = previous.group() if previous else ''
    split = bool(tail and tail[-1].isalpha() and token
                 and token[0].isalpha())
    value = 0.0

    if token.lower().strip(' -') == 'of':
        nouns = re.findall(r'[^\W\d_]+', tail.lower())
        noun = nouns[-1] if nouns else ''
        article = nouns[-2] if len(nouns) > 1 else ''
        if noun == 'matter':
            value = 9.4 if article == 'a' else 5.5
            if tail.rstrip().endswith('Matter'):
                value = 7.5
            if article == 'subject':
                value = 2.5
        elif noun == 'matters':
            value = 3.9
        elif noun in OF_NOUNS:
            ordinary, indefinite = OF_NOUNS[noun]
            value = indefinite if article in ('a', 'an') else ordinary
    elif word in ('matter', 'frontmatter'):
        value = 7.8 if split else 4.3
        if token.strip() == 'Matter':
            value = 6.0
        if previous == 'a':
            value = 8.0
        elif (previous in ('no', 'not', 'it', 'does', 'really')
              or previous.endswith(("n't", 'n’t'))):
            value = 0.2
        elif previous in ('white', 'gray', 'grey', 'subject', 'front'):
            value = 6.0
        elif previous in ('that', 'this'):
            value = 2.5
        elif previous == 'lives':
            value = 2.8
    elif word == 'matters':
        value = 1.8
    elif word == 'materials':
        value = 0.6 if token.strip()[:1].isupper() else 0.25
    elif word == 'material':
        value = 0.2
    elif word.endswith(('mater', 'materi')):
        value = 6.0
    elif word.endswith(('materia', 'matéria')):
        value = 4.4
    elif word.endswith(('materias', 'matiere', 'matière')):
        value = 5.5 if split else 4.2
    elif word == 'marie':
        value = 6.6 if split else 5.1
    elif word in ('maria', 'maría'):
        value = 4.2 if split else 2.8
    elif word in ('mary', 'mammary'):
        value = 4.0 if split else 2.3
    elif word.endswith('maths'):
        value = -9.5 if split else -5.3
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -1.5
    return (doc, raw), value

programs.haiku:
"""Component layers.1.mlp.down_proj:5381: a detector for the word "matter" and its cousins.

The unit reads the current word (its letters, lower-cased, built up token by token), the word
before it and the one before that, and writes a value into the residual stream:

- "matter" and "matters": strongly positive. Strongest after "a" ("a matter of course", "as a
  matter of law", about 8); medium after "the" (about 4) or "front" and "white" (about 8);
  near zero in "no matter" and "doesn't matter".
- " of" right after "matter": the largest value, when the idiom is "a matter of" (about 10),
  medium for "the matter of" (about 4.5), small for "subject matter of" (about 1.5). " of"
  after "question" is about 3.5, after "manner" about 2, after "issue" about 1.5.
- the same root in other languages and spellings: mater, materia, matière, materie, Russian матер-
  (as in матер-инский, "maternal"), and 物質 (Japanese for "substance"): about 5. English
  "material" and "materials" stay near zero.
- the names Marie, Maria, María, Mary and Mare: about 3.5. Matt: about 1.5.
- "maths" (British for mathematics) strongly negative, about -6, and the "s" of "math" + "s".
  "maid" is negative too, about -4.
- Everything else is 0.

The word tracker is a carry: a word grows token by token and resets at a non-letter or at a
document boundary.
"""

import re

READS = ()

TAIL = re.compile(r"[^\W\d_]+$")
MATTER = {"matter", "matters"}
MATER = {"mater", "maters", "materia", "materie", "materi", "matière", "matières", "matiere",
         "матер", "матері", "物質", "物质", "materiel"}
NAMES = {"marie", "maria", "maría", "mary", "mare"}
NEGATIVE = {"maths": -6.0, "maid": -4.0, "maids": -4.0}
OF_AFTER = {"question": 3.5, "manner": 2.0, "issue": 1.5}
NEGATED = {"no", "not"}
DETERMINER_A = {"a", "an"}
DEMONSTRATIVE = {"this", "that", "these", "it", "its"}


def step(carry, prefix, upstream):
    word, last, before_last = carry if carry is not None else ("", "", "")
    if prefix.position > 0 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        word, last, before_last = "", "", ""
