            value = 0.2
        elif last in DETERMINER_A or last in ("white", "front"):
            value = 8.0
        elif last in DEMONSTRATIVE:
            value = 2.0
        else:
            value = 4.0
    elif word == "of" and last in MATTER:
        if before_last in DETERMINER_A:
            value = 10.0
        elif before_last == "the":
            value = 4.5
        elif before_last == "subject":
            value = 1.5
        else:
            value = 7.0
    elif word == "of":
        value = OF_AFTER.get(last, 0.0)
    elif word in MATER:
        value = 5.0
    elif word in NAMES:
        value = 3.5
    elif word == "matt":
        value = 1.5
    else:
        value = NEGATIVE.get(word, 0.0)
    return carry, float(value)

