"""Approximate a mixture of article and structured-text introducer responses.

A word-frequency language guess separates homographs such as Portuguese 'do'
and English 'do'. Selected singular article prefixes receive larger values
than plural ones; an apostrophe can complete an elided French/Italian article.
The code branch recognizes fresh declarations, Java imports and PHP variables.
HTTPS separators and document-opening title/PHP labels have separate responses.
Other tokens are predicted as zero.
Miscellaneous numerical and rare-token responses are not reproduced.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
# Singular and plural definite articles, including fused prepositions.
ARTICLES = {
    'fr': ('la le du au l', 'les aux'),
    'it': ('il lo la l del della dello dell dal dalla dallo dall '
           'nel nella nello nell al alla allo all sul sulla sullo sull',
           'le gli delle degli dalle dagli nelle negli alle agli sulle sugli'),
    'es': ('la el del al', 'las los'),
    'pt': ('a o do da no na ao pelo pela', 'as os dos das nas aos pelos pelas'),
    'de': ('am im zum zur vom beim ins ans', ''),
    'hu': ('a az', ''),
    'el': ('ο η το τον την του της', 'οι τα των'),
}
ARTICLES = {lang: (set(a.split()), set(b.split()))
            for lang, (a, b) in ARTICLES.items()}
LANGUAGES = ('en', 'fr', 'it', 'es', 'pt', 'de', 'hu', 'el', 'ro',
             'pl', 'tr', 'cs', 'nl')
DECLARATIONS = {'const': 1.3, 'let': 1.2, 'var': 1., 'int': .8,
                'float': .5, 'double': .65, 'String': .8, 'final': .7,
                'auto': 1., 'Dim': 1.2, 'using': .4}

@lru_cache(maxsize=50000)
def frequencies(word):
    return tuple(zipf_frequency(word.lower(), lang) for lang in LANGUAGES)


def guess_language(text):
    words = re.findall(r'[^\W\d_]+', text)[-16:]
    words = [w for w in words if len(w) > 1]
    if not words:
        return None
    scores = [0.] * len(LANGUAGES)
    for word in words:
        for i, f in enumerate(frequencies(word)):
            scores[i] += f
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, last_value = '', '', 0.
    else:
        _, recent, previous, last_value = carry
    token = prefix.token_strings[-1]
    form = token.strip().lower()
    boundary = (token[:1].isspace() or not recent or
                not recent[-1:].isalnum())
    value = 0.
    article_form = any(form in a or form in b for a, b in ARTICLES.values())
    if boundary and recent and token.strip() != 'L' and article_form:
        lang = guess_language(recent + ' ' + form)
        if lang is None:
            lang = 'fr' if form in {'la', 'le', 'les', 'l'} else None
        singular, plural = ARTICLES.get(lang, (set(), set()))
        if form in singular:
            value = .85
            if form in {'del', 'della', 'dell', 'il', 'l'}:
                value = 1.10
            if lang == 'hu':
                value = .65
        elif form in plural:
            value = .45
        if value > 0. and token.strip()[:1].isupper():
            value *= .7
    elided = previous.strip().lower() in {'l', 'dell', 'all', 'nell', 'dall'}
    if token in {"'", '’'} and elided:
        value = max(0., last_value)
        if guess_language(recent) in {'fr', 'it'}:
            value = 1.10
    # Allow indentation, source line numbers, and diff +/- markers.
    line = recent.replace('\\n', '\n').replace('\\t', '\t').rsplit('\n', 1)[-1]
    line_start = bool(re.fullmatch(r'\s*(?:[+-]\s*)?(?:\d+\s+)?', line))
    inline_declaration = (form in {'let', 'var', 'const'} and
                          bool(re.search(r'[;{}]\s*$', recent)))
    if (line_start or inline_declaration) and token.strip() in DECLARATIONS:
        value = DECLARATIONS[token.strip()]
    if form == 'import' and line_start:
        value = 1.55 if re.search(r';\s*$', recent) else .10
    # Some Greek articles are split into a tau and their final vowel/nasal.
    if token in {'ο', 'η', 'ν'} and re.search(r'(?:^|\W)[τΤ](?:[ηο])?$', recent):
        value = 1.05
    if token == ' in' and re.match(r'\s*for\s+\S+', line):
        value = .55
    if token == '://' and previous.endswith('https'):
        value = 1.25
    if recent == '<?' and token == 'php':
        value = 2.29
    if recent == 'Title' and token == ':':
        value = 4.41
    if token == 'www' and previous == '://':
        value = .7
    php_context = '<?php' in recent or ('$' in recent and ';' in recent)
    if form == '$' and line_start and php_context:
        value = 1.0
    if token == '<|endoftext|>':
        recent, token = '', ''
    return (doc, (recent + token)[-400:], token, value), value

