"""A beginning-of-context signal, with strength set by the token's surface.

It is strongest for isolated letters, weaker for space-prefixed words, and
small for sentence-ending punctuation. An unchanged, repeating prefix keeps
this signal alive. Elsewhere it is nearly silent, except for a single space
after a space-only token. The numerical strengths are training-set averages;
they do not capture the substantial differences between individual words.
"""
import regex

READS = ()


def beginning_strength(text):
    word = text.strip()
    spaced = text.startswith(' ')
    if not word:
        if text == ' ':
            return -3.55
        if text == '\t':
            return -6.5
        if not text.strip(' '):
            return -5.7
        return -3.2
    if word.startswith('<|'):
        return -4.15
    if word.isdecimal():
        if word == '0':
            return 0.58
        if word == '1':
            return -5.35
        return -3.0
    if word.isascii() and word.isalpha():
        if len(word) == 1:
            return -6.35 if spaced else -9.95
        if spaced:
            return -4.1 if word.islower() and len(word) <= 3 else -5.05
        if word.isupper():
            return -6.0
        if word.istitle():
            return -7.6 if len(word) >= 4 else -6.85
        return -6.5
    if any(ch.isalpha() for ch in word):
        if word.isascii():
            return -6.6
        if regex.search(r'\p{Script=Han}', word):
            return -3.65
        if len(word) == 1 and regex.match(r'\p{Script=Cyrillic}', word):
            return -4.75 if spaced else -8.75
        return -3.8 if spaced else -4.9
    if '\n' in text:
        return -3.2 if spaced else -4.15
    if spaced:
        return -1.95 if word[0] in '\"\'`' else -2.55
    if word[0] in '.,;:!?':
        return -1.5
    if word[0] in '([{':
        return -5.5
    if word[0] in ')]}':
        return -3.1
    if word[0] in '\"\'`':
        return -7.3
    return -3.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous_text, unchanged = '', True
    else:
        _, previous_token, previous_text, unchanged = carry
        unchanged = unchanged and token == previous_token
    if unchanged:
        value = beginning_strength(text)
    elif text == ' ' and previous_text and not previous_text.strip(' '):
        value = -0.54
    else:
        value = 0.0
    return (doc, token, text, unchanged), value

"""Spelling fragments after ch/sh and related sibilants.

Short e-led fragments are positive, especially ch+es/est; short a-led
fragments are negative, especially ar and an. Longer, already combined
pieces are usually weaker. A response can persist onto the k of Russian
-chesk- adjectives. A double middle-dot separator is negative too.
These are spelling rules, not word meanings; all other tokens get zero.
"""
import re
from anyascii import anyascii

READS = ()
ONSET = re.compile(r'ch|sh|zh|cz|[чшжщčšžż]|ش')
END = re.compile(r'(ch|sh|zh|cz|[чшжщčšžż]|ش)$')


def continuation(onset, tail, previous):
    # The first vowel and following consonant determine the main response.
    s = anyascii(tail).lower()
    if not s:
        return 0.0
    n = len(tail)
    first = anyascii(tail[0]) if onset in 'чшжщ' or onset == 'ش' else tail[0]
    second = anyascii(tail[1]) if n > 1 else ''
    if first == 'á':
        return -3.4
    if first in ('l', 'k', 'r') and second == 'e' and n <= 3:
        return 3.5 if first == 'l' else 1.7
    cyrillic = onset in 'чшжщ'
    if first == 'e':
        if second == 's':
            if onset == 'ч' and n <= 3:
                return 10.2
            if onset in 'жшщ' and n <= 3:
                return 4.5
            if s == 'ester':
                return 8.5
            if s == 'estr':
                return 5.2
            if len(previous.strip()) <= 3:
                if n == 2:
                    return 8.0 if previous.strip() in ('ch', 'sch') else 2.0
                return 8.0 if s == 'est' else 1.0
            return 0.5
        if second in ('n', 'e'):
            return 0.0
        if n <= 2:
            return {'b': 5.3, 'l': 3.7, 'r': 3.0}.get(second, 2.1)
        return 2.2 if second == 'l' and n <= 3 else 0.6
    if first == 'a':
        if cyrillic and s == 'ay':
            return -6.0
        if n > 3:
            return -0.6
        if n == 2:
            if second == 'r':
                return -7.5 if onset in 'чж' else -3.5 if cyrillic else -1.7
            if second == 'n':
                if onset == 'ж':
                    return -9.0 if len(previous) <= 2 else -5.0
                return -5.5 if len(previous.strip()) <= 3 else -1.0
            return {'d': -4.0, 'k': -4.0, 'u': -4.1,
                    'v': -3.5, 'l': -2.2, 't': -2.7}.get(second, -1.7)
        return -2.7 if second == 'n' else -1.0
    if first in 'ou':
        return -4.0 if s == 'ou' else -1.2 if n <= 2 else -0.3
    if first == 'i' and second in ('s', 'n'):
