                             'a': -0.6, 'er': 1.0, 'e': 0.2,
                             'u': -0.8}.get(s, 0.0)
                elif m[0] == 'ч':
                    value = {'er': 3.5, 'em': 1.0}.get(s, 0.0)
                elif m[0] == 'ж' and s == 'el':
