"""A mixture of local textual patterns, not a single semantic topic.

The main positive cases are comma-grouped digits, 'one of' constructions,
French negation, and quoted-speech attribution. Initial title/code markers
have separate, token-sensitive responses and a coarse shape baseline.
Double-middle-dot-only prefixes are negative. Other body text stays near
zero: most token-specific background variation is deliberately unmodeled.
Width variants are normalized. State resets at document boundaries and
end-of-text, retaining only a short suffix, one token and a separator flag.
"""
import re
import unicodedata

READS = ()

# Document-opening heading and programming-syntax markers.
OPENERS = {
    'Title': -8.432, 'int': -7.972, 'def': -4.617,
    'const': -3.833, 'function': -3.361, 'public': 1.55,
    '<|im_start|>': 0.402,
}
# Forms of 'one' and their partitive prepositions.
PARTITIVES = {
    'of': {'one'},
    'de': {'uno', 'una', 'un', 'une', 'alguno', 'alguna'},
    'des': {'un', 'une'}, 'dei': {'uno', 'una'},
    'das': {'uma', 'algumas'}, 'dos': {'um', 'alguns'},
    'der': {'eine', 'einer', 'eines', 'einem', 'einen'},
    'из': {'один', 'одна', 'одной', 'одним', 'одного'},
}
REPORTING = {
    'said', 'says', 'asked', 'replied', 'answered', 'cried',
    'sagte', 'sagt', 'рассказал',
}
NEGATIVE_STEM = re.compile(
    r"\b(?:don|doesn|didn|isn|aren|wasn|weren|haven|hasn|hadn|"
    r"can|couldn|wouldn|shouldn|won|mustn|needn|ain|n)['’\\ ]*$", re.I)


def predict(carry, token, document):
