        value = 0.52
    elif word == 'the' and re.search(r'\bone of$', tail, re.I):
        value = 0.19
    elif word == 'pas':
        value = 1.50 if re.search(r"\bne\b|\bn['’]", tail[-70:], re.I) else 0.176
