    elif s in {'nt', 'ont'} and re.search(
            r'\b(?:am|is|are|was|were|do|does|did|have|has|had|can|could|'
            r'would|should|will|must|d)$|(?:Does|Is|Can|Could|Would|Should)$',
            tail, re.I):
