"""Layer 1, MLP down-projection, component 5386.

Plain-language summary. This component is silent on nearly every token (its causal
importance is near zero almost everywhere; its typical size is a few hundredths). It
switches on, to roughly +1, in a few recognisable places:

  * the last digit of a thousands-grouped number, such as the final 0 of "5,000" or the 5
    of "1,235" (about +0.75);
  * the word "of" directly after "one" ("One of the ...") (about +0.85);
  * a negation ending: French "pas" as in "je n'ai pas" (about +1.2), and "nt" after an
    auxiliary, as in "couldn't" or "didn't" (about +1.2);
  * the middle-dot filler token "··" of a dotted leader (about -0.8; seen in one document).

Document starts are special: the first token of a document has no left context, so its
value depends only on its own spelling. A first token spelled as a word with no leading
space (a capitalised name or a code keyword such as "int", "def") goes about -0.4; a
first digit goes +0.3; "<|im_start|>" goes +0.4; other first tokens stay at 0.

The program is stateless. It looks at the last few tokens and at whether a new
document has just started.
"""

READS = ()

DIGITS = set("0123456789")
AUXILIARIES = {"did", "does", "do", "could", "should", "would", "can", "ca", "wo", "must",
               "might", "may", "will", "shall", "is", "was", "are", "were", "have", "has", "had"}


def first_token_value(s):
    """Activation of a document's first token, from its own spelling alone."""
    if s.strip().isdigit():
        return 0.3
    if s == "<|im_start|>":
        return 0.4
    if s[:1].isalpha():
        return -0.4
    return 0.0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, first_token_value(cur)
    prev = toks[-2]
    # digit , d d d : the third digit of a thousands group
    if len(toks) >= 5 and cur in DIGITS and prev in DIGITS and toks[-3] in DIGITS \
            and toks[-4] == "," and toks[-5] in DIGITS:
        return carry, 0.75
    if cur == " of" and prev.strip().lower() == "one":
        return carry, 0.85
    if cur == " pas":
        return carry, 1.2
    if cur == "nt" and prev.strip().lower() in AUXILIARIES:
        return carry, 1.2
    if cur == "··":
        return carry, -0.78
    return carry, 0.0

"""Layer-1 MLP down_proj, component 5387.

What it responds to (from data): a few specific tokens get large, sign-consistent values.
- Repeated middle-dot leaders "··" (in runs of dots): strongly negative, about -1.
- The Russian/Ukrainian standalone preposition/particle "у" (as in "если у вас",
  "у нас"): positive, about +0.6.
- Chinese formal linking words that take a following verb or noun: 并 (and), 于
  (in/at, as in 取决于, 立足于), 由于 (due to): positive, +0.4 to +0.6.
- The first token of a document (right after <|endoftext|>): mildly negative, except
  chat-template markers <|im_start|>/<|im_end|> (negative, about -0.5) and a Java
  "package" line (strongly positive, about +1.7).
Everything else is predicted as 0, which is near its typical value.
"""
READS = ()

RUSSIAN_U = {" у", " У", "У"}
LINKERS = {"并": 0.5, "並": 0.3, "于": 0.4, "由于": 0.4, "但由于": 0.5}
CHAT_MARKERS = {"<|im_start|>", "<|im_end|>"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if tok == "··":
        return None, -1.0
    if tok in RUSSIAN_U:
        return None, 0.6
    if tok in LINKERS:
        return None, LINKERS[tok]
    if first:
        if tok in CHAT_MARKERS:
            return None, -0.5
        if tok == "package":
            return None, 1.7
        return None, -0.1
    return None, 0.0

