        if s.startswith(('ni', 'ny', 'ng')):
            return 0.0
        if len(s) == 1:
            return -6.2
        if len(s) <= 3:
            return -2.1

    # Or it supplies an after the preceding i/y/j.
    if p.endswith(('y', 'i', 'j')) and s.startswith('an'):
        if s.startswith('ang'):
            return -0.2
        if len(s) <= 4:
            if p[-1] == 'y':
                return -4.8
            if p[-1] == 'j':
                return -0.5
            return -2.4 if token.isascii() else -3.6
    if p.endswith(('y', 'i')) and s.startswith('en'):
        return -0.4

    # Entire syllables inside short fragments, with common suffix endings.
    m = re.fullmatch(r'([a-z]{0,2})([iyj])an(a|e|i|o|s|t|ne|ce)?', s.strip())
    if m and not kana:
        lead, glide, tail = m.groups()
        tail = tail or ''
        if glide == 'y':
            if not token.isascii():
                return -3.7
            if not lead:
                return -6.2
            if len(lead) == 1 and token[:1].isspace():
                return -1.8
            return -3.8
        if glide == 'j':
            return 0.0 if token[:1].isspace() else -0.7
        if len(lead) >= 2:
            return -0.6
        if lead and tail:
            return -0.3
        if tail in ('i', 'ne'):
            return -5.1
        if tail in ('a', 'e', 'o'):
            return -2.5
        if tail:
            return -0.9
        return -2.8 if token.isupper() else -1.3
    if not kana and re.fullmatch('[a-z]?ien(?:ne|s)?', s.strip()):
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    return None, predict(prefix.token_strings[-1], previous)

"""Approximate a local traversal signal, dominated by 'through'.

The preceding English word sets its strength: crossing verbs are strongest,
then traversal/inspection verbs and path nouns. Other motion words, object
pronouns and numbers receive intermediate values; generic -ed words are
negative. 'Though' is weak after even/as or sentence boundaries, intermediate
after commas, and strong otherwise. Spelling relatives, several translations,
'a tour of', and an echo on the following 'the' are also recognized. This is a
lexical approximation, not a semantic parser. State resets between documents.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Verbs used for traversing a space, a sequence, or material being inspected.
TRAVERSE = set('''go come pass move run travel flow drive navigate trace loop
iterate progress get work look read see think browse scroll sift sweep sort
live wade follow continue break pull thread shine penetrate climb rummage
put take carry send lead bring guide
venture push drift rush peek'''.split())
CROSS = set('cut walk step slip fall strike'.split())
PATH = set('''way path route line loop journey channel road course section hole
opening tunnel passage'''.split())
OBJECTS = set('me you him her it us them'.split())


@lru_cache(maxsize=4096)
def describe(word):
    bases = set(wordnet.base_forms(word, 'verb')) | {word}
    motion = 'verb.motion' in wordnet.categories(word)
    # These general operators have incidental motion senses in the dictionary.
    motion = motion and not bases & {'do', 'make', 'access', 'reach'}
    return bool(bases & TRAVERSE), bool(bases & CROSS), bool(motion)


def through_value(text):
    if not text:
        return -2.3
    text = text.replace('\\n', ' ').replace('\\t', ' ')
    words = re.findall(r'[a-z]+|[0-9]+', text.lower())
    w = words[-1] if words else ''
    if re.search(r'[.!?]\s*$', text):
        return -1.1
    if re.search(r'[^\w\s]\s*$', text):
        return 0.0
    traverse, cross, motion = describe(w)
    if cross:
        return 9.0 - 1.5 * w.endswith('ed')
    if traverse:
        return 6.0 - 1.2 * w.endswith('ed')
    if w in PATH:
        return 5.0
    if w in OBJECTS:
        prior = words[-2] if len(words) > 1 else ''
        return 4.5 if any(describe(prior)) else 1.3
    if w.isdigit():
        return 1.5
    if motion:
        return 2.5 + 1.5 * w.endswith('ing') - w.endswith('ed')
    return 1.5 * w.endswith('ing') - 1.5 * w.endswith('ed')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous, echo = '', '', 0.0
    else:
        _, text, previous, echo = carry
    token = prefix.token_strings[-1]
    w = token.strip().lower()
    value = 0.0
    if w in ('through', '-through', 'thru'):
        value = through_value(text)
    elif w == 'though':
        if re.search(r'\b(even|as)\s*$', text, re.I):
            value = 0.1
        elif re.search(r'[,;]\s*$', text):
            value = 1.25
        elif not text or re.search(r'[.!?\n(]\s*$', text):
            value = 0.3
        else:
            value = 3.8
    elif w in ('thorough', 'trough'):
        value = 1.3
    elif w == 'breakthrough':
        value = 2.5
    elif w in ('durch', 'через', 'през', 'przez'):
        value = 1.6
    elif w.endswith('through'):
        value = 8.0
    elif w in ('rough', 'rought') and text.lower().endswith('th'):
        value = 8.5
    elif w == 'ru':
        value = 13.0 if text.lower().endswith('th') else 1.5
    elif w == 'u' and text.lower().endswith('tr'):
        value = 3.2
    elif (w in ('воз', 'ь') and
          (text + token).lower().endswith(('сквоз', 'сквозь'))):
        value = 7.8
    elif w == 'the' and previous in ('through', '-through', 'thru'):
        value = 0.12 * echo
    elif w == 'of' and previous == 'tour':
        value = 3.0
    return (doc, (text + token)[-100:], w, value), float(value)

"""Approximate a mixture of document-header and source-formatting responses.

The strongest negative cases are opening Title colons, early // header padding,
and separators after @param. Smaller rules recognize annotations, imports,
Go receivers and attribution lines. Opening defaults use whitespace, numbers,
word classes and code markers.
Unrecognized positions are zero; fine lexical and contextual variation is omitted.
"""
import re

READS = ()
DOC_QUOTES = ("\"\"\"", "'''")
FUNCTION_WORDS = set(
    'the this that these those to of for with in on at by from as '
    'and or but if you your i me my we our he she it they their'.split()
)


def opening(token):
    """Coarse token-shape defaults at a fresh attention/document boundary."""
    word = token.strip()
    if token == 'Title': return -0.78
    if token == 'package': return -1.12
    if token.startswith('---'): return 0.73
    if token.startswith(('/*', '<!--', '--') + DOC_QUOTES): return 2.0
    if token.startswith('//'): return 0.9
    if token.startswith('#!'): return 1.0
    if word and set(word) == {'#'} and len(word) <= 6:
        return -0.8 if len(word) <= 2 else -0.4 * len(word)
    if token.startswith('#'): return -1.8 if token == '#define' else -0.6
    if token == '@': return -2.5
    if not word: return 0.24
    if token.startswith('<|'): return 0.29
    if word.isdecimal(): return -0.13
    if token[0].isspace() and word.lower() in FUNCTION_WORDS: return 0.30
    if token.isascii() and token.isalpha():
        pronouns = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}
        return 0.15 if token.lower() in pronouns else -0.20
    return 0.0


def estimate(token, previous, recent, age, first):
    line = recent.rsplit('\n', 1)[-1]
    word = previous.strip()
    if age == 0:
        return opening(token)
    if age == 1 and previous == 'Title' and token == ':':
        return -15.45
    if age == 2 and first == '---\n' and previous == 'title' and token == ':':
        return -4.49

    # The large file-header response fades away from the document's beginning.
    if first == '//\n':
        if previous == '//' and token == ' ':
            return -54.0 / (age + 1)
        if age == 3 and previous == ' ' and token == ' ':
            return -9.5
        if token == ' Created' and line.strip() == '//':
            return -25.0 if age == 2 else -8.0
        if token == ' by' and previous == ' Created':
            return -6.0 - 18.0 / (age + 1)

    tag = re.search(
        r'@(param|return|type|brief|subpackage|version)[ \t]*$', recent
    )
    if tag:
        name = tag[1]
        if token and set(token) == {' '}:
            if name == 'param':
                return -10.2
            return -4.0 if name in {'brief', 'subpackage'} else -1.0
        if token == ' {':
            return -6.2 if name == 'param' else -1.1
        if name == 'param':
            if token in (':', ' :', ' $', ' <'):
                return -6.0
            if token == ' \\':
                return -2.8
    if token == '@Override' or (token == 'Override' and recent.endswith('@')):
        return 1.05
    if recent.endswith('@') and token in {'package', 'var', 'since'}:
        return {'package': 6.5, 'var': 1.7, 'since': 1.2}[token]
    if token == 'inline' and recent.endswith('#['):
        return 3.4
    if token.strip() == 'javax' and word == 'import':
        return -2.0
    if token == ' (' and word == 'func':
        if previous.startswith('\t'):
            return -0.5
        return -2.6 if line == 'func' else -0.9
    if token == 'package':
        if re.search(r'\*/\s*$', recent):
            return -4.5
        if recent.endswith('\\use'):
            return 5.3
    if token == ' Created' and line.strip() in {'*', '///'}:
        return -4.0
    if (token == ' by' and word == 'Created'
            and line.strip().startswith(('*', '/'))):
        return -3.7
    if token == '##' and re.search(r'####$', line):
        return -6.1
    if token == '··' and previous == token:
        return 1.02
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous, recent, first = 0, '', '', token
    else:
        _, age, previous, recent, first = carry
    value = estimate(token, previous, recent, age, first)
    return (doc, age + 1, token, (recent + token)[-180:], first), value

"""A small parser for scholarly cross-reference and hyperlink notation.

Strong pulses mark the end of a reference destination, an escaped label, or
reference attributes. Labels and attribute values get smaller pulses. A closing
comma or full stop weakens the response. Ordinary text stays close to zero.
The parser keeps only the last 240 characters and resets at document boundaries.
"""
import re

READS = ()
REFERENCE_NAMES = {'fig', 'tab', 'table', 'sec', 'app', 'fn'}


def closing(s, strength):
    """References joined directly to sentence punctuation have weaker pulses."""
    if '.' in s:
        return 0.65
    if ',' in s:
        return 1.4
    if s.count(')') == 1:
        return 3.0
    if s.count(']') > 1:
        return 1.1
    return strength


def predict(s, before):
    link = re.search(r'\]\(([^\s)]{0,180})$', before)
    if s == '){':
        return 13.9 if link else 0.0

    attr = re.search(r'\)\{([^{}\n]{0,160})$', before)
    if attr:
        if s == '="':
            return 5.9 if attr[1].endswith('ref-type') else 0.5
        if s.startswith('"}'):
            return 3.8 if 'ref-type=' in attr[1] else 0.5
        if attr[1].endswith('ref-type="'):
            return {'fig': 5.8, 'table': 1.35, 'ref': 1.5}.get(s, 0.0)

    citation = re.search(r'\[@[^\]\n]{0,160}$', before)
    escaped = re.search(r'\\\[([^\]\n]{0,160})$', before)
    if s.startswith(']\\') and citation:
        return 4.7
    if s == ']' and before.endswith(']\\'):
        return 2.3
    if citation and s.startswith(']'):
        return closing(s, 3.7)
    if escaped:
        label = escaped[1].replace('\\_', '_').replace('\\^', '^')
        label = label.rstrip('\\')
        if re.fullmatch(r'[A-Za-z][A-Za-z0-9_:./^= -]{1,140}', label):
            if s == '\\':
                return 3.5 if any(c in label for c in ' ^=') else 9.7
            if s.startswith(']') and before.endswith('\\'):
                return closing(s, 6.0)
            if s == '\\_':
                return 2.9

    command = re.search(r'\\(cite\w*|[a-z]*ref|label)\*?\{[^{}]{0,160}$', before)
    if command and s.startswith('}'):
        strength = 4.8 if command[1] == 'label' else 4.5
        if command[1].startswith('cite'):
            strength = 2.5
        if command[1] == 'href':
            strength = 1.0
        return closing(s, strength)

    heading = re.search(r'(?:\{#|^#)([^{}\n]{0,160})$', before)
    if heading:
        if s.startswith('}'):
            return 4.4
        if not heading[1] and s.isalpha():
            return 1.4
    if s.lower() in ('fig', 'tab', 'sec'):
        if before.endswith(('data-label="', '\\[')) or (command and before.endswith('{')):
            return 1.5
    if s.startswith('"}') and 'data-label="' in before[-100:]:
        return 3.8

    if link:
        label = link[1]
        if s.lower() in REFERENCE_NAMES:
            return 4.4 if s.lower() in ('fig', 'tab') else 2.15
        if s == '-' and label.lower().endswith('bib'):
            return 8.4
        if s.isdigit() and label.lower().endswith('bib-'):
            return 2.5
        if s.isdigit() and label.lower().endswith(tuple(REFERENCE_NAMES)):
            return 1.15
        if label == '#' and s.isalpha():
            return 1.5
        if s.startswith('.') and s[1:].isalpha():
            return 0.8
        if s.startswith(')'):
            return 1.0
    if s.startswith(']') and '\n' in s:
        line = before.rsplit('\n', 1)[-1]
        return 0.44 if '/' in line or '__' in line else 0.06
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-240:]), predict(token, before)

programs.haiku:
"""Layer-1 MLP down-projection component 5398: fires on the closing and attribute
tokens of reference syntax, mainly the Quarto/Pandoc cross-reference link

    [Table 1](#tab1){ref-type="table"}

where it is large on `){` (after the `](#...` link), on `="` and `"}` of the
`{ref-type="..."}` attribute, and on the `fig`/`tab` word right after `(#` or
`ref-type="`. Weaker firings: the `}` that closes a LaTeX \\label{...} or a
\\includegraphics{...pdf} path, the `]` that ends a bracketed tool-output line, and the
closing brackets of a \\cite or [@key] citation. Everywhere else it predicts 0.
"""

READS = ()

WINDOW = 16  # tokens of the same document looked back over
REF_WORDS = ("fig", "tab", "app", "sec", "eq")


def _recent(prefix):
    """The decoded text of up to WINDOW tokens before this one, in this document."""
    doc = prefix.document_ids[-1]
    toks = []
    for s, d in zip(prefix.token_strings[-WINDOW - 1 : -1], prefix.document_ids[-WINDOW - 1 : -1]):
        if d == doc:
            toks.append(s)
    return "".join(toks)


def _open_after(text, opener):
    """True if `opener` (e.g. '\\label{') occurs in `text` with no closing brace after it."""
    i = text.rfind(opener)
    return i >= 0 and "}" not in text[i:]


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    before = _recent(prefix)
    value = 0.0
    if tok == "){" and "](#" in before:
        value = 13.0  # the brace that opens {ref-type=...} after a figure/table link
    elif tok == '="' and before.endswith("-type"):
        value = 6.0  # ref-type="
    elif tok in REF_WORDS and (before.endswith("](#") or before.endswith('ref-type="')):
        value = 5.0  # the word after (# or ref-type="
    elif tok.isdigit() and before.endswith(("#fig", "#tab", "#app", "#sec")):
        value = 2.5  # the number after the word, as in (#fig1
    elif tok == '"}' and 'ref-type="' in before:
        value = 4.0  # closing quote of the attribute
    elif tok in ("}", "}\n") and _open_after(before, "\\label{"):
        value = 4.0  # \label{260}
    elif tok == "}" and before.endswith(".pdf"):
        value = 3.0  # \includegraphics[...]{fig.pdf}
    elif tok == "]\n" and ("working directory" in before or "[Command" in before):
        value = 1.0  # the ] ending a tool-output status line
    elif tok in ("],", "])", "},", "]{", "}.") and ("\\cite" in before or "[@" in before):
        value = 1.5  # end of a citation
    return None, value

