"""Approximate the start of a code annotation, especially a trailing comment.

Completed statements and extra horizontal padding strengthen comment openers;
indentation alone does not. Numbered listings and escaped-newline code get
intermediate responses. Most ordinary text is assigned zero. Smaller rules
cover padding, SQL/VB comments, and named declaration annotations.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    _, prev, line = carry if carry and carry[0] == doc else (doc, '', '')
    logical = line.replace('\\n', '\n').rsplit('\n', 1)[-1]
    code, t = logical.rstrip(), s.strip()
    end = code[-1:]
    padded = bool(prev and not prev.strip(' \t'))
    leading, serialized = s.startswith((' ', '\t')), '\\n' in line
    numbered = bool(re.fullmatch(r'\s*\d+\t\s*', logical))
    value = 0.0
    # C-style openers include Doxygen forms and punctuation merged into a token.
    m = re.fullmatch(r'([;()[\]{}\s]*)(//(?:[/!]?<?|#)|/\*{1,2}<?)', s)
    marker = m[2][:2] if m else '#' if t == '#' else ''
    if marker and '\n' not in s:
        before = m[1].strip() if m else ''
        code = (code + before).rstrip()
        end = code[-1:]
        if not code or code in ('+', '-', '#', '//', '`', '```'):
            value = 3.5 if serialized and leading and padded else -0.2
        elif numbered:
            value = 3.0 if leading else 2.0
        elif end == ';':
            value = 12.0
        elif end in (')', ']', '}'):
            value = 12.0 if padded else 8.0
        elif marker == '#' and not padded:
            if leading and (end in ('"', "'", ',') or
                            re.match(r'^\s*(import|from)\b', logical)):
                value = 11.0
            elif end == ':' and re.search(r'\b(if|while|def|class|for)\b', code):
                value = 9.0
            elif leading and end.isdigit() and '=' in code and len(code) < 160:
                value = 10.0
        elif marker == '/*' and not leading and not padded:
            value = 0.0
        elif re.match(r'^\s*#{1,6}\s', logical):
            value = 0.0
        elif padded:
            value = 11.0
        else:
            value = 7.0 if end in ('(', '[', '{', ',') else 3.0 if leading else 0.4
        if marker == '/*':
            value *= 0.85
        if marker == '//' and before and set(before) <= set(')]'):
            value = 2.3  # This merged shape also occurs in integer division.
        if serialized and code:
            value *= 0.65
    elif t == '--' and leading and end == ';':
        value = 11.0
    elif t == ';' and leading and re.match(
            r'^\s*(mov|push|pop|add|sub|call|ret|xor|jmp|cmp|lea)\b', logical, re.I):
        value = 11.0
    elif t == '%' and leading:
        value = 7.5 if end == ';' else 6.5 if padded and end in (')', ']') else 0.0
        if end in ('"', "'", ','):
            value = 1.5 if end == ',' else 0.4
    elif t == 'COMMENT' and re.search(r'\b(DEFAULT|NULL|varchar|TEXT|COLUMN)\b',
                                      logical, re.I):
        value = 6.0
    elif t == "'" and (prev.strip() == 'COMMENT' or
                       re.match(r'^\s*(Dim|Const)\b', logical)):
        value = 5.7
    elif t in ('throws', 'noexcept') and end == ')':
        value = 1.7
    elif t in ('Override', '@Override') and ('@' in t or prev.endswith('@')):
        value = 0.9
    elif t == '@@' and leading:
        value = 1.6
    elif t == '#[':
        value = 1.0
    elif s and s.isspace():
        if not prev:
            value = -0.4
        elif prev == '\t' and numbered:
            value = 1.5
        elif '\n' not in s and end == ';':
            value = 1.2
        elif len(s) >= 32:
            value = min(2.5, len(s) / 64)
        elif '\n' not in s and end in (')', ']', '}'):
            value = 0.16
    return (doc, s, (line + s).rsplit('\n', 1)[-1][-512:]), value

"""A partial lexical predictor, not a general reconstruction of the MLP.

Predicts negative values for some Chinese entering and totality expressions,
and positive values for public openness and employment. CC-CEDICT supplies
these meaning classes. Initial written control escapes and nested Chinese
title brackets are separate strong positive cases. Small English/code cues are also retained.
Most of the component's other lexical variation is deliberately left at zero.
"""
from functools import lru_cache
import cedict
import regex

READS = ()
HAN_WORD = regex.compile(r'\p{Script=Han}{2,}')
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
TOTALITY = frozenset((
    'whole', 'entire', 'total', 'comprehensive', 'overall',
    'the whole world', 'worldwide; global', 'all categories',
))


@lru_cache(maxsize=16000)
def meaning_value(text):
    if not HAN_WORD.fullmatch(text):
        return 0.0
    glosses = cedict.glosses(text)
    if 'to enter; to go into' in glosses:
        return -1.5
    if any(g in TOTALITY or 'all kinds of' in g for g in glosses):
        return -0.4
    if any(g in ('employment', 'to get a job', 'to seek employment',
                 'to engage in') or g.startswith('to hire')
           for g in glosses):
        return 0.7
    if any(g == 'to be open (to the public)' or g == 'open; overt; public'
           for g in glosses):
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, text, True, 0, 100)
    _, first, initial_run, title_depth, kana_age = carry
    initial_run = initial_run and text == first
    value = meaning_value(text)
    if initial_run and text == r'\t':
        value = 2.0
    elif initial_run and text == r'\n':
        value = 1.48
    elif text == '〈' and title_depth and kana_age > 24:
        value = 2.7
    elif text == 'import':
        value = 0.76 if initial_run else -0.10
    elif text == ' from':
        value = -0.03
    elif text == ' into':
        value = 0.06
    elif text == '://':
        value = 0.085
    title_depth = max(0, title_depth + text.count('《') - text.count('》'))
    kana_age = 0 if KANA.search(text) else kana_age + 1
    return (doc, first, initial_run, title_depth, kana_age), value

"""A full-stop response, stronger in numbers than at numbered-list markers.

Standalone periods get a negative pulse. Closing punctuation and line breaks
merged into the token soften it; dot-plus-word tokens barely respond. The
last two tokens distinguish decimals/versions, list numbering and dotted
abbreviations. A short document-initial transient fades with position.
"""
import math

READS = ()


def predict(text, previous, before_previous, position):
    word = text.strip()
    before = previous.rstrip()
    last = before[-1:]
    value = 0.0
    if text == '.':
        if position == 0:
            return -0.03
        value = -1.03 - 1.5 / math.sqrt(position + 1)
