    '<|im_start|>': -0.042,
    '<|im_end|>': -0.009,
    '<|endoftext|>': -0.007,
    '<think>': -0.195,
    '</think>': -0.013,
    '<tool_call>': 0.022,
    '</tool_call>': 0.118,
