                    return -0.21
                if word.lower() in PREPOSITIONS | PRONOUNS | CONJUNCTIONS:
                    return -0.08
                return -0.30
            if word.isupper():
                return -0.35
            if word.istitle():
                return -0.13
            return 0.025
