"""Component layers.1.mlp.down_proj:5407.

What it does: it fires on the token that starts a member access on the object
the code is currently inside: the `._` of `self._lock`, `this._x`, `cls._x`
(also `.__` dunder names and `.#` JS private fields), and the `->` of PHP/C++
`$this->x`. It also fires on the `::` of `std::` or `Self::`, and on `this.state`
(React). Outside code it fires weakly on "present time" phrases: positive on
"this / each / next / last time", "by now" and the continuation of the Chinese
or Japanese word for "now" (今), and negative on "this day" and "present day"
(idioms like "to this day"). Everywhere else it predicts 0. Values are typical
activations in training text.
"""

READS = ()

PRIVATE_ACCESS = {"._", ".__", ".#", "->_"}
SELF_WORDS = ("self", "this", "cls")
SCOPE_WORDS = {"std", "Self", "static", "self"}
TIME_WORDS = {"This", "this", "Each", "each", "Every", "every", "next", "Next", "last", "Last"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    word = prev.strip(" (\t$=[")
    value = 0.0
    if word.endswith(SELF_WORDS) and tok in PRIVATE_ACCESS:
        value = 6.5
    elif word.endswith("this") and tok in (".state", ".setState"):
        value = 5.0
    elif word == "this" and tok == "->":
        value = 2.2
    elif word in SCOPE_WORDS and tok == "::":
        value = 2.8
    elif word == "今":
        value = 2.9
    elif tok == " time" and word in TIME_WORDS:
        value = 2.0 if word != "this" else 1.0
    elif tok == " now" and word == " by":
        value = 5.0
    elif tok == " day" and word in ("this", "present"):
