"""Activation of layers.1.mlp.down_proj:5408: a sparse time-reference feature.

Positive on deictic time words in news-style prose: "last" ("last year"), "next"
("next week"), "this" ("this season"), "recently", "yesterday". Negative on temporal
connectives ("after", "when", "before", "until", "including") and on "several",
"straight", "consecutive". "after"/"when"/"before" are pushed further negative right after a
time span ("years after"). "last"/"next" after "the/in/of/a" and "this" after "in" are
weak or zero ("in this paper"). Everything else predicts 0.
"""

TIME_UNITS = {"year", "years", "week", "weeks", "month", "months", "day", "days", "night", "nights",
              "season", "seasons", "time", "times", "hour", "hours", "decade", "century", "summer",
              "winter", "spring", "autumn", "morning", "evening"}
DEICTIC = {"last": 1.2, "next": 0.5, "this": 0.3, "recently": 0.5, "yesterday": 0.9, "earlier": 0.5}
SUBORD = {"after": -0.8, "when": -0.4, "before": -0.35, "until": -0.3, "where": -0.2, "including": -1.1}
QUANT = {"several": -0.55, "straight": -0.9, "consecutive": -0.4}
def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings[-2:]]
    w = words[-1]
