            value = 2.4
        elif re.search(r'\b(?:PASS|FAIL|DEBUG)$', before):
            value = 0.9
        elif re.search(r'\.rs$', before):
            value = 2.2
        elif re.search(r'\.[A-Za-z_][A-Za-z_0-9]{0,12}$', before):
            value = 0.85
    if s.strip() == 'PASS' and before.rstrip().endswith('---'):
        value = -1.1

