            ('to look',8.2),
            ('worth',1.4), ('to acquire',0.9), ('to obtain',0.15),
            ('to think',0.6), ('to feel',0.6), ('to make',1.2),
        ):
            if meaning in gloss:
                return value
        if any(x in gloss for x in ('must not', 'may not', 'cannot',
                                     'to acquire', 'to know')):
            return 0.2
        return None
    return None


def predict(token, before):
    if not any(c in token for c in '的得地'):
        return -0.52 if token == '의' else 0.0
    index = max(token.rfind(c) for c in '的得地')
    marker = token[index]
    left,tail = before + token[:index],token[index+1:]
    word = preceding_word(left)
    known,verb,adj,noun,ratio = grammar(word)
    single = len(word)==1
    if marker == '得':
        lexical = lexical_de(left+'得')
        if lexical is not None:
            value = lexical
        elif re.search('[\u3040-\u30ff]', left[-16:]):
            value = 0.0
        else:
            value = 2.0 + 4.0*verb + 2.5*ratio + 1.3*adj - noun
        if tail:
            value *= 0.65 if tail in ('很','好') else 0.2
        return value
    if marker == '地':
        value = 0.5 + 0.55*adj - 0.6*single
        return value if token == '地' else 0.15*value
    # A small grammatical-class fit, not a token-identity lookup.
    value = (0.2 + 0.25*adj - 0.17*noun + 1.75*ratio
             + 0.45*single + 1.0*(single and verb) + 0.23*verb)
    if word in PRONOUNS or word in DETERMINERS:
        value -= 1.7
    if word in LOCALIZERS:
        value -= 1.6
    if not known:
        value += 0.43
    if token != '的':
        if not tail:
            value *= 0.75 if single and verb and not noun else 0.35
        else:
            value *= 0.35 if len(tail)==1 else 0.1
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc,0,b'')
    _,count,recent = carry
    token = prefix.token_strings[-1]
    value = predict(token,recent.decode('utf-8','replace'))
    if count == 1 and recent == b'Title' and token == ':':
        value = -15.69
    recent = (recent + prefix.token_bytes[-1])[-48:]
    return (doc,count+1,recent),float(value)

"""An opening-token response, plus punctuation ending small list labels.

At a document's opening, estimate a broad response from token shape and
basic grammar and spelling. It persists while the prefix repeats
the same token. Elsewhere the clearest cue is punctuation after a list
label: second labels (2, b) are strongest, then third labels (3).
There is also a small bias for b/m-initial spellings (voiced bilabial
letters), after transliteration. These are coarse averages, not a lexical
reconstruction of every token.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
ARTICLES = {'a', 'an', 'the'}
PRONOUNS = set('i you he she it we they me him her us them my your his '
               'its our their this these those'.split())
QUESTIONS = set('what why when where who whom whose which how'.split())
HELPERS = set('am is are was were be being been do does did have has had '
              'can could may might will would shall should must'.split())
CONJUNCTIONS = set('and or but nor so yet if because although while when '
                   'as that than whether'.split())


@lru_cache(maxsize=32768)
def bilabial_initial(token):
    first = re.search(r"[a-z]", anyascii(token).lower())
    return bool(first and first.group() in "bm")


def opening(token):
    word = token.strip()
    if not word:
        return 1.2 if '\t' in token else 0.7
    if word.startswith('<|') and word.endswith('|>'):
        return 0.35
    if '\ufffd' in word:
        return 0.35
    if word.startswith('\\'):
        return 1.8
    if word.startswith(('"""', "'''")):
        return 2.5
    if word[0] in '._(' and any(c.isalpha() for c in word):
        return 1.35
    if not any(c.isalnum() for c in word):
        if len(word) > 1:
            return min(1.8, 0.6 + 0.3 * len(word))
        if word in "\"'":
            return 0.0
        return 0.3 if word in '.,:;!?/()[]{}' else 0.9
    if not word.isascii():
        return 0.35
    if word.isdigit():
        return 0.62
    lower = word.lower()
    capital = word[0].isupper()
    if lower in ARTICLES or lower in PRONOUNS:
        return 0.25
    if lower in QUESTIONS:
        return -0.7 if capital else 0.35
    if lower in HELPERS:
        return -0.35 if capital else 0.4
    if lower in CONJUNCTIONS:
        return 0.0 if capital else 0.3
    return 1.1 if bilabial_initial(token) else 0.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        line, first, repeated = '', token, True
    else:
        _, line, first, repeated = carry
        repeated = repeated and token == first
    value = opening(token) if repeated else (
        0.022 if bilabial_initial(token) else 0.005)
    if not repeated and token in ('.', ')', '、'):
        label = re.search(r'(?<!\w)([0-9]+|[A-Za-z])$', line)
        if label:
            name = label.group().lower()
            at_start = token == '、' or not line[:label.start()].strip(
                ' \t\r|>*#([（')
            if name in ('2', 'b'):
                value = 0.56 if at_start else 0.12
            elif name == '3':
                value = 0.45 if at_start else 0.10
            elif name == '1':
                value = 0.055 if at_start else 0.015
            elif at_start and name.isdigit():
                value = 0.12 if len(name) == 1 else 0.04
            elif at_start and name in 'acdefgh':
                value = 0.12
    line = (line + token).replace('\\n', '\n').split('\n')[-1][-160:]
    return (doc, line, first, repeated), value

