from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
NEGATORS = ('不', '没', '无', '未', '非', '勿', '别')
DETERMINERS = set('这 那 该 此 每 各 其 这是 那些 这些'.split())
PEOPLE = set(
    '群众 职工 干部 干部职工 党员 同学们 人民 学生 孩子们 粉丝'.split()
)
PROGRESS = set(
    '发展 进步 前进 梦想 梦 理想 创新 科技创新 高质量 建设 未来'.split()
)
MODALS = set('要 想 想要 必须 应该 应当 需要 我们要'.split())


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    s = SIMPLIFY.convert(text.strip())
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    opening = first or (carry[2] and carry[1] == text)
    han = bool(regex.fullmatch(r'\p{Script=Han}+', s))
    value = -0.001
    if han:
        value += 0.006
        if s.startswith(NEGATORS):
            value += 0.034
        if s == '不':
            value += 0.24
        if s.startswith('第'):
            value -= 0.04
        if regex.fullmatch('[一二三四五六七八九十百千万两]+', s):
            value += 0.017
        if regex.fullmatch('[一二三四五六七八九十]是', s):
            value -= 0.76
        if s in DETERMINERS:
            value += 0.043
        if s in PEOPLE:
            value -= 0.134
        if s in PROGRESS:
            value -= 0.192
        if s in MODALS:
            value -= 0.105
        if not first and carry[3].endswith(
            ('不', '没', '不能', '不可', '不得', '不要', '勿')
        ):
            value += 0.12
    if s.startswith('<|im_') or s in {
        '<think>', '</think>', '</tool_response>'
    }:
        value -= 0.042
    if opening:
        value -= 0.12
        value -= 0.138 if han else 0.
        value -= 0.141 if s.isascii() and s.isdigit() else 0.
        value -= 0.151 if text.isspace() else 0.
        value -= 0.07 if regex.fullmatch('[A-Za-z]+', s) else 0.
        value -= 0.05 if regex.fullmatch('[A-Z][a-z]+', s) else 0.
        if s and all(not c.isalnum() for c in s):
            value += 0.045
        if s.startswith('<|'):
            value -= 0.283
        if s and set(s) == {'·'}:
            value -= 1.222
    second = not first and (
        prefix.position == 1
        or prefix.document_ids[-2] != prefix.document_ids[-3]
    )
    if second and carry[1] == '1' and text == '2':
        value = -1.81
    return (doc, text, opening, s), value

"""Short k-rich word fragments, and their following endings.

Nearby repetitions of k give positive values, especially in short fragments.
Cyrillic/Greek k and the Japanese k-series are recognized too. Arabic/Persian
kaf fragments instead give negative values. A run of middle dots is positive.
These are coarse character rules, not token-specific activation estimates.
"""
import re

READS = ()
KANA = 'かきくけこカキクケコ'
K_LETTERS = str.maketrans({c: 'k' for c in 'кКκΚ' + KANA})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '')
    _, word, previous, before = carry
    text = prefix.token_strings[-1]
    token = text.lower().translate(K_LETTERS)
    continuing = bool(text and text[0].isalpha())
    distance = len(word) - word.rfind('k') if 'k' in word else 20
    repeated = token.count('k') >= 2 or (continuing and 'k' in word)
    value = 0.003
    if text.count('·') >= 2:
        value = 2.22
    elif 'ك' in text:
        if len(text) == 1:
            value = -3.80
        else:
            value = -2.26 if len(text) <= 4 else -0.50
    elif 'ک' in text:
        value = -1.62 if len(text) == 1 else -1.29
    elif continuing and 'ك' in previous:
        if previous.endswith(('ك', 'ک')):
            value = -3.73 if len(word) <= 3 else -1.95
        else:
            value = -0.97 if len(previous) <= 4 else -0.45
    elif continuing and 'ک' in previous:
        value = -1.18 if len(word) <= 1 else -1.75
    elif 'k' in token and (repeated or not previous):
        if distance <= 3:
            if any(c in text for c in KANA):
                value = 0.50 if len(text) == 1 else 0.0
            else:
                value = 1.93 if len(text) <= 3 else 0.30
        elif 'ko' in token:
            value = 3.21 if len(text) <= 4 else 0.40
        else:
            value = 0.74 if not previous else 0.20
    elif 'k' not in token and continuing:
        if 'k' in previous or (word.count('k') >= 2 and 'k' in before):
            if word.count('k') >= 2:
                if len(word) <= 4 and distance == 1:
                    value = 1.40
                else:
                    value = 0.23 if len(word) <= 6 else 0.0
            elif len(word) <= 1:
                value = 0.14
    # A lone k followed by another short k-fragment is especially strong.
    latin_k = 'k' in token and not any(c in text for c in 'кКκΚ' + KANA)
    if latin_k:
        old = word if continuing else ''
        if len(text) <= 3 and old == 'k':
            value += 1.87
        if len(text) <= 5 and token.count('k') >= 2:
            value += 0.93
    word = re.split(r'[^\w\u0300-\u036f]+', word + token)[-1][-40:]
    return (doc, word, token, previous), value

"""A sparse detector of written signposts, rather than ordinary subject matter.

Scientific/patent headings and announcements of the author's next step give
negative pulses. Examples, abbreviated references and connective commas give
positive pulses. Magnitudes approximate training averages. Unrecognized text
gets zero, apart from a small document-start adjustment. Only 200 trailing
characters are remembered, and each new document clears them.
"""
import re

READS = ()

SECTION = re.compile(
    r'(?:^|\n)\s*[#*\d.()| -]*\s*'
    r'(introduction|discussion|results|background|methods|conclusions?|'
    r'preliminaries|proof|remark)\s*$', re.I)


def response(before, token, first):
    text = (before + token)[-200:]
    low, word = text.lower(), token.strip().lower()
    value = 0.18 if first else 0.0

    # Section headings, with a stronger response after a large paragraph break.
    if word and word[-1].isalpha():
        heading = SECTION.search(text)
        if heading:
            name = heading[1].lower()
            value += {'introduction': -1.5, 'discussion': -3.2,
                      'background': -1.4, 'results': -0.6}.get(name, -0.4)
            if re.search(r'\n\n\n[^\n]*$', before):
                value += {'introduction': -10.1, 'results': -2.3}.get(name, -1.0)
            if first and name == 'background' and token.strip().isupper():
                value -= 5.3

        # Standard terminology of patents and mathematical exposition.
        if text.endswith(('Related Art', 'Background Art')):
            value -= 12.3
        elif re.search(r'\b(?:prior|related) art$', low):
            value -= 4.4
        if text.endswith('DETAILED DESCRIPTION'):
            value -= 5.9
        elif low.endswith('brief description'):
            value -= 1.5
        if low.endswith('background of'):
            value -= 7.4
        if re.search(r'\binvention(?: generally| also)? relates$', low):
            value -= 7.3
        if low.endswith('present invention'):
            value -= 0.6
        if low.endswith(('first embodiment', 'second embodiment')):
            value -= 1.6
        if re.search(r'\\(?:begin|end)\{proof$', text):
            value -= 3.6

    if token.isspace() and '\n' in token:
        heading = SECTION.search(before)
        if heading:
            value -= 1.0
            if heading[1].lower() == 'introduction':
                value -= 1.8
        if re.search(r'\n={3,}$', before):
            value -= 0.9

    # Punctuation completing examples and abbreviated cross-references.
    if token.startswith('.'):
        if re.search(r'\bi\.e[.,]+$', low):
            value += 1.4 + (0.5 if ',' in token else 0.0)
        elif re.search(r'\be\.g[.,]+$', low):
            value += 1.2 + (0.5 if ',' in token else 0.0)
        elif re.search(r'\b(?:figs?|eqs?|sec|cf)\.$', low):
            value += 0.6
        elif re.search(r'\bet al[.,]*$', low):
            value += 0.4
    if word.isdigit() and len(word) == 1:
        if re.search(r'\b(?:fig(?:ure)?s?|tables?|eq(?:uation)?s?)\.?\s+$', before, re.I):
            value -= 0.6
        elif re.search(r'\[\s*$', before):
            value -= 0.1

    # Discourse transitions: their comma is often the strongest part.
    if token == ',':
        prev = before.rstrip().lower()
        if re.search(r'\bfor (?:example|instance)$', prev):
            value += 1.0
        elif re.search(r'\bin (?:particular|fact)$', prev):
            value += 0.7
        elif re.search(r'\b(?:similarly|indeed|clearly|sure|interestingly)$', prev):
            value += 1.3
        elif re.search(r'\b(?:however|moreover|furthermore|hence|therefore|additionally)$', prev):
            value += 0.3
        elif re.search(r'\b(?:first|now)$', prev):
            value -= 0.5
    if low.endswith('for example'):
        value += 0.3
    if low.endswith('by the way'):
        value -= 3.3
    if word in ('alternatively', 'first'):
        if not before or re.search(r'[\n.]\s*$', before):
            value -= 0.25 if word == 'alternatively' else 0.4

    # The author announcing a step or referring to the written explanation.
    if word == 'we':
        if re.search(r'[,;:]\s*$', before):
            value -= 0.4
        if re.search(r'\b(?:now|next|first|finally),?\s*$', before, re.I):
            value -= 1.0
        if re.search(r'\b[Tt]o [^.!?;\n]{3,100},\s*$', before):
            value -= 0.2
        if re.search(r'\b(?:study|considerations),\s*$', before, re.I):
            value -= 1.2
        if re.search(r'\b(?:paper|section|appendix)\s*$', before, re.I):
            value -= 1.6
    if re.search(r'(?:^|[,.\n]|\bso|\bnow)\s*(?:we|i) need$', low):
        value -= 0.4
    if word == 'to' and re.search(r'\b(?:we|i) need\s+to$', low):
        value -= 0.25
    if re.search(r'\b(?:we|i|me) first$', low):
        value -= 0.75
    if word in ('described', 'discussed', 'explained', 'illustrated'):
        if re.search(r'\b(?:be|is|are|as|been)\s*$', before, re.I):
            value -= 1.0
            if re.search(r'\bwill be\s*$', before, re.I):
                value -= 2.0
    if word in ('above', 'below', 'previously', 'later'):
        if re.search(r'\b(?:described|discussed|explained|shown|illustrated)\s*$', before, re.I):
            value -= 0.8
    if re.search(r'\b(?:have|has|been) shown$', low):
        value += 0.7
    if low.endswith('showed that'):
        value += 0.8
    if re.search(r'\b(?:begin|end)\{$', low):
        value -= 0.8
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = response(before, token, first)
    return (doc, (before + token)[-200:]), float(value)

"""A mostly negative Slavic relation-word detector.

Recognize prepositions (for/from/to/before/after, etc.), a few compound
prepositions, and Slavic stems for sequence, middle and viewpoint. The
last piece of a split word can be stronger than an unsplit spelling.
Latin-letter matches require recent words to be more frequent in Polish
or Czech than in English, Portuguese, Spanish or German. This keeps
English 'do' and 'red' from normally triggering it. Russian 'на' ('on')
has a small positive response instead.
"""
import regex as re
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
# Magnitudes for Cyrillic prepositions, not arbitrary vocabulary items.
PREPOSITIONS = {
    'для': 9.3, 'из': 4.8, 'до': 5.0, 'после': 5.5,
    'перед': 5.0, 'среди': 5.2, 'без': 2.2, 'от': 1.7,
    'над': 2.5, 'у': 0.8, 'под': 0.7, 'между': 1.4,
    'около': 3.0, 'вокруг': 3.4, 'кроме': 3.0, 'ради': 1.3,
    'в': 0.1, 'с': 0.35, 'к': 0.15, 'на': -0.3,
    'вместо': 4.5,
}
LATIN_PREPOSITIONS = {
    'do': 5.8, 'dla': 6.5, 'od': 3.0, 'bez': 2.0,
    'nad': 1.4, 'przed': 2.5, 'pred': 4.7, 'podle': 5.0,
}
COMPOUNDS = {
    ('во', 'время'): 5.9, ('с', 'помощью'): 4.8,
    ('на', 'основе'): 4.3, ('в', 'основе'): 2.5,
    ('в', 'течение'): 3.0, ('в', 'рамках'): 2.2,
    ('из', 'за'): 4.7,
}
WORD = re.compile(r'[^\W\d_]+\Z')
WORDS = re.compile(r'[^\W\d_]+')

COMPOUND_NOUNS = {p[1] for p in COMPOUNDS}


def latin_language(text):
    words = WORDS.findall(text.lower())[-20:]
    if not words:
        return None
    scores = {
        lang: sum(zipf_frequency(w, lang) for w in words) / len(words)
        for lang in ('cs', 'pl', 'en', 'pt', 'es', 'de')
    }
    best = max(('cs', 'pl'), key=scores.get)
    others = max(scores[l] for l in ('en', 'pt', 'es', 'de'))
    return best if scores[best] > others + 0.5 else None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = (previous + token)[-256:]
    m = WORD.search(text)
    word = m.group().lower() if m else ''
    magnitude = PREPOSITIONS.get(word, 0.0)
    if magnitude:
        if word != token.strip().lower():
            magnitude *= 1.5
        if word == 'после' and m.group()[0].isupper():
            magnitude *= 1.35
    elif word in COMPOUND_NOUNS:
        words = WORDS.findall(text.lower())
        magnitude = COMPOUNDS.get(tuple(words[-2:]), 0.0)
    elif word in LATIN_PREPOSITIONS or word.endswith(('d', 'д')):
        cyrillic = bool(re.search(r'\p{Script=Cyrillic}', word))
        stem = anyascii(word)
        candidate = (word in LATIN_PREPOSITIONS
                     or stem.endswith(('sled', 'hled', 'red')))
        language = None
        if candidate and not cyrillic:
            language = latin_language(previous)
        if cyrillic or language:
            magnitude = LATIN_PREPOSITIONS.get(word, 0.0)
            if word == 'do' and language == 'pl':
                magnitude = 7.2
            # sled = follow/sequence; hled = look; sred = middle.
            if not magnitude and stem.endswith('sled'):
                prefixed = stem.endswith(('posled', 'nasled', 'dusled'))
                magnitude = 10.0 if prefixed else 6.5
                # An entire Cyrillic stem in one token is weaker.
                piece = anyascii(token.strip().lower())
                if cyrillic and piece.endswith('sled'):
                    magnitude *= 0.3
            elif not magnitude and stem.endswith('hled'):
                magnitude = 4.5
            elif not magnitude and stem.endswith('red'):
                if stem.endswith(('posred', 'neposred')):
                    magnitude = 7.5
                elif stem.endswith(('sred', 'stred')):
                    magnitude = 5.5
                    piece = anyascii(token.strip().lower())
                    if cyrillic and piece.endswith('sred'):
                        magnitude *= 0.3
                elif stem.endswith('pred') and cyrillic:
                    magnitude = 0.9
                else:
                    magnitude = 1.5 if cyrillic else 3.5
    return (doc, text), -magnitude

"""Recognize letter-symbol tokens, especially outside their usual script.

Greek names and isolated Greek glyphs get a positive response. A recent
same-script context suppresses glyph responses: Greek prose is not a formula.
Cyrillic ge/el/pe in Latin context and tool-call markup are strong cases.
Smaller rules cover Hebrew/Thai glyphs, long s, chat boundaries, repeated middle
dots, and document-initial code or title syntax.
UTF-8 fragments are joined before interpreting a character; history resets at
packed-document boundaries.
"""
import unicodedata
from functools import lru_cache

READS = ()
GREEK_NAMES = set('alpha beta gamma delta epsilon zeta eta theta iota kappa '
                  'lambda mu nu xi omicron pi rho sigma tau upsilon phi chi '
                  'psi omega'.split())
MARKERS = {'<tool_call>': 2.23, '</tool_call>': 0.23,
           '<|im_start|>': -0.12, '<|im_end|>': -0.21,
           '</think>': 0.36}


@lru_cache(maxsize=32768)
def describe(data):
    pending = b''
    try:
        text = data.decode('utf8')
    except UnicodeDecodeError as e:
        if e.reason == 'unexpected end of data':
            text = data[:e.start].decode('utf8', 'replace')
            pending = data[e.start:]
        else:
            text = data.decode('utf8', 'replace')
    letters = [c for c in text if c.isalpha()]
    script = ''
    if letters:
        for candidate in ('LATIN', 'GREEK', 'CYRILLIC', 'HEBREW', 'THAI'):
            if all(candidate in unicodedata.name(c, '') for c in letters):
                script = candidate
                break
    inferred = script
    if not letters:
        if pending.startswith((b'\xce', b'\xcf')):
            inferred = 'GREEK'
        elif pending.startswith((b'\xd0', b'\xd1')):
            inferred = 'CYRILLIC'
    return text, pending, script, inferred, ''.join(letters)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    raw = prefix.token_bytes[-1]
