        carry = (document, b'', (), '', 0)
    _, pending, recent, previous, position = carry
    text, pending, script, inferred, letters = describe(pending + raw)
    s = text.strip()
    name = s.lstrip('._(')
    # A script's prevalence among the last sixteen letter-bearing tokens.
    fraction = recent.count(inferred) / max(1, len(recent))
    novelty = max(0.0, 1.0 - 2.0 * fraction)

    value = 0.0
    if s in MARKERS:
        value = MARKERS[s]
    elif name.lower() in GREEK_NAMES:
        value = 0.69
        if name.lower() in {'mu', 'nu', 'xi', 'pi', 'chi', 'eta'}:
            value -= 0.22
        if name.lower() in {'delta', 'lambda'}:
            value -= 0.26
        if raw.startswith(b' ') and name.lower() in {'mu','nu','xi','chi','psi'}:
            value -= 0.35
        if not name.islower():
            value *= 0.35
