        value = 0.73
        if s.isupper():
            value -= 0.25
        if not letters:
            value -= 0.38  # Only the beginning of a Greek UTF-8 character.
        value *= novelty
    elif inferred == 'CYRILLIC' and len(letters) <= 2:
        value = 0.40
        if s.isupper():
            value += 0.73
        if letters in {'Г', 'л', 'п'}:  # Ge, el and pe: common corruption forms.
            value += 5.63
        if not letters:
            value += 5.34
        latin_fraction = recent.count('LATIN') / max(1, len(recent))
        value *= novelty * latin_fraction
    elif script in {'HEBREW', 'THAI'} and len(letters) <= 2:
        value = 0.91 * novelty
    elif s == 'ſ':
        value = 0.20
    elif s == '··' and previous == s:
        value = -0.78
    elif position == 1 and previous == 'Title' and s == ':':
        value = -2.74
    elif position == 0 and s == '//':
        value = 3.51 if '\n' in text else 0.39
    elif position == 0 and s in {"'use", '"use'}:
        value = 1.05

    if script:
        recent = (recent + (script,))[-16:]
    return (document, pending, recent, s, position + 1), float(value)

