"""Layer-1 MLP down-projection component 5421, as a rule over the newest token.

What it responds to (values are rough means of its activation, fit on sampled text):
  * the tool-call opener "<tool_call>": strongest, about +2.2 (closer "</tool_call>": +0.2),
  * a Greek letter, written as a symbol (α, β, γ) or spelled out as a maths name
    (alpha, sigma, eta, phi, ...), when the text just before it is mostly Latin
    script: about +0.5. Inside a non-Latin passage it stays near 0,
  * the closing think tag "</think>": about +0.4,
  * the middle dot "·" (dot leaders and the like): about -0.6,
  * the chat markers "<|im_start|>" and "<|im_end|>": about -0.15,
  * a fragment of a multi-byte character that does not decode alone (U+FFFD): about +0.07.
Everything else is 0. The rule is stateless apart from a short window of the preceding
tokens, used to measure how Latin the surrounding text is.
"""

import unicodedata

READS = ()

GREEK_NAMES = set(
    "alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu nu xi omicron "
    "pi rho sigma tau upsilon phi chi psi omega".split()
)
WINDOW = 16


def _is_greek(s):
    if any(unicodedata.name(ch, "").startswith("GREEK") for ch in s):
        return True
    return s.strip().lower().lstrip(".(") in GREEK_NAMES


def _latin_share(prefix, t):
    """Share of ASCII letters among the letters in the WINDOW tokens before position t."""
    letters = [ch for i in range(max(0, t - WINDOW), t) for ch in prefix.token_strings[i] if ch.isalpha()]
    if not letters:
        return 0.0
    return sum(ch.isascii() for ch in letters) / len(letters)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = prefix.position
    if s == "<tool_call>":
        value = 2.2
    elif s == "</tool_call>":
        value = 0.2
    elif s == "</think>":
        value = 0.4
    elif s in ("<|im_start|>", "<|im_end|>"):
        value = -0.15
    elif "·" in s:
        value = -0.6
    elif _is_greek(s) and _latin_share(prefix, t) > 0.5:
        value = 0.5
    elif s == "�":
        value = 0.07
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A code-punctuation boundary detector, with initial-token word-shape baselines.

Look only at the current token and at most 300 preceding characters. Closing
parentheses in call-like/code-like text, standalone closing brackets, escaped
line endings, `if`, fences and separators receive positive values. Punctuation
merged with a newline is usually much weaker. Reset history at each document.
The values are training averages, not a parser or token-identity lookup.
Lexical differences and irregular initial-token responses remain unexplained.
"""
import re

READS = ()
CODE_HINTS = set('''
    def class function fn struct interface enum public private protected static
    const let var final int long float double bool boolean char void string
    true false null None nil undefined True False import include using package
    await self console printf
'''.split())
CODE_MARKS = ('==', '!=', '=>', '->', '()', ';', '{', '}')


def response(token, before, prev, position):
    s = token.strip()
    line = before.rsplit('\n', 1)[-1]
    newline = token.endswith(('\n', '\r'))
    prev_word = bool(re.search(r'\w$', prev))
    prev_close = prev.rstrip().endswith((')', ']', '}'))
    local_code = any(mark in before[-80:] for mark in CODE_MARKS)
    code_words = any(w in CODE_HINTS
                     for w in re.findall(r'[A-Za-z_]+', before))
    quoted = line.count('"') % 2 == 1 or line.count("'") % 2 == 1

    # A closing parenthesis is strongest after a call or function header.
    if ')' in s:
        if newline:
            return -0.014
        call = bool(re.search(r'[A-Za-z_][A-Za-z_0-9.]*\([^()]*$',
                              before[-120:]))
        if not call:
            if not local_code:
                return 0.291 if '(' in s else 0.047
            return 0.554 if code_words else 0.169
        if '.' in s:
            return -0.059
        if code_words:
            header = re.search(r'\b(def|fn|function|public|private|protected|void)\b',
                               line)
            return 0.934 if header else 0.651
        if ',' in s:
            return -0.046
        return 0.752 if quoted else 0.340

    # Repeated punctuation includes Markdown fences and visual separators.
    repeated = len(s) >= 2 and len(set(s)) == 1 and not s[0].isalnum()
    if repeated:
        if not s.isascii():
            return 0.973
        if '`' in s:
            return 0.180 if line.strip() else 0.688
        if len(s) >= 3 and s[0] in '-=_':
            if '=' in s:
                return 0.071
            return 0.856 if len(s) <= 3 else 0.218
        return 0.012

    # The initial-token baseline is different from the within-document one.
    if position == 0:
        if len(s) <= 3:
            return 0.482 if s and s[0].isupper() else 0.227
        return 0.019 if s.isalpha() else 0.410

    if s == 'if':
        if not local_code:
            return 0.061
        return 0.212 if prev_word else 0.668

    # Backslashes often introduce escaped newlines after a code delimiter.
    if '\\' in s:
        if prev_close:
            return 0.538
        if '{' in s:
            return 0.416
        if prev_word:
            return 0.030
        if token.startswith((' ', '\t')):
            return -0.004
        if len(s) <= 1:
            return 0.766 if code_words else 0.325
        return 0.083

    if s and not s.strip(')]}'):
        if newline:
            return 0.018
        return 0.196 if prev_word else 0.919
    if '{' in s:
        return 0.071
    if "'" in s:
        if any(c.isalnum() for c in s):
            return -0.014
        return 0.159 if quoted else 0.032
    return 0.0001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, prev, position = '', '', 0
    else:
        _, before, prev, position = carry
    token = prefix.token_strings[-1]
    value = response(token, before, prev, position)
    return (doc, (before + token)[-300:], token, position + 1), value

"""Detect written forms of load, with stronger loading/loader responses.

The rule works across token splits, includes Chinese carry/load characters
and Japanese/Korean load-road spellings, and also recognizes laden.
Payload and workload are weaker than load; loading and loader are stronger.
Two side responses are document-initial Title: and Cyrillic -лас- (often
in reflexive past verbs). There is a small positive document-start baseline.
All state resets at document boundaries. Many smaller responses are omitted;
this is a spelling-sensitive approximation, not a general semantic detector.
"""
import re

READS = ()
LOAD = re.compile(r'load(er|ers|ing|ed|s|able)?$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        _, tail, position = carry
    text = tail + token
    lower = text.lower()
    match = LOAD.search(lower)
    value = -0.002

    if match and match.end() > len(tail):
        before = lower[:match.start()]
        ending = match.group(1) or ''
        if before.endswith('pay'):
            value = -0.12
        elif before.endswith(('down', 'up')):
            value = -0.9
        elif before.endswith('work'):
            value = -1.2
        elif ending in ('er', 'ers'):
            value = -5.8
        elif ending == 'ing':
            value = -4.4
        elif ending == 'ed':
            value = -4.0
        elif before.endswith(('un', 're', 'over')):
            value = -4.8
        elif token.lower().startswith('.load'):
            value = -1.1
        else:
            value = -2.9
    elif lower.endswith('laden'):
        value = -3.8
    elif '下载' in token:
        value = -1.4
    elif '载' in token or '載' in token:
        value = -2.6
    elif '卸' in token:
        value = -1.7
    elif text.endswith('ロード'):
        value = -5.3
    elif text.endswith('로드'):
        value = -4.5
    elif token == 'ас' and tail.endswith('л'):
        value = 6.0

    if position == 0 and value == -0.002:
        value = 0.18
    if position == 1 and tail == 'Title' and token == ':':
        value = -7.17
    return (doc, text[-24:], position + 1), value

"""A detector for English partitive and relational noun phrases.

Predict negative writes at heads such as 'a series', 'this kind', and
'large number', often introducing an 'of' complement.  Articles, quantifiers,
size adjectives and possessives distinguish these uses from bare words and
noun compounds.  Responses are approximate, shared across semantic families;
no following token is inspected.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

def words(text):
    return set(text.split())

SELECT = words('this that these those some any what which such another each every')
POSSESSIVE = words("my your his her its our their 's ’s")
SIZE = words('''large small big huge vast enormous great wide broad narrow
    high low higher lower maximum minimum total full considerable substantial
    significant sufficient excessive massive''')
CONTRAST = words('''different other all both various several certain particular
    specific same new entire diverse many few numerous main first second next last''')
NUMBERS = words('''one two three four five six seven eight nine ten eleven twelve
    hundred thousand million''')
ARTICLES = words('a an the')
DETERMINERS = ARTICLES | SELECT | POSSESSIVE

# Strength of the indefinite ('a/an ...') construction.
STRENGTHS = [
    ('set collection series', 3.1),
    ('variety assortment plethora myriad multitude', 2.),
    ('group pair piece member trio', 1.7),
    ('list array sequence', 1.5),
    ('mix mixture combination bunch host', 1.4),
    ('form class version source instance', 1.),
    ('understanding knowledge love choice use ability means', .8),
]
STRENGTH = {w: k for group, k in STRENGTHS for w in group.split()}
HEAD = set(STRENGTH) | words('''number amount degree level type kind sort
    range sense lack lot''')

@lru_cache(maxsize=4096)
def adjective(w):
    return 'adjective' in wordnet.parts_of_speech(w)


# Response columns: bare, the, a/an, selecting determiner, possessive,
# size adjective, contrast/specification adjective, numeral.
def predict(s, previous, before, history=()):
    w = s.strip().lower()
    plural = w.endswith('s') and w[:-1] in HEAD
    root = w[:-1] if plural else w
    if root not in HEAD:
        return 0.
    p = previous
    # The order here gives mutually exclusive grammatical contexts.
    context = (1 if p == 'the' else 2 if p in {'a', 'an'} else
               3 if p in SELECT else 4 if p in POSSESSIVE else
               5 if p in SIZE else 6 if p in CONTRAST else
               7 if p.isdigit() or p in NUMBERS else 0)
    if root == 'number':
        value = (-.5, -1.5, -.8, -1., -.6, -2.7, -1.3, -.6)[context]
        if plural and context in {1, 3, 7}:
            value *= .35
        if p in {'what', 'which'}:
            value = .6
        if p in {'maximum', 'minimum', 'max', 'min'}:
            value = -3.5
    elif root in {'amount', 'degree', 'level'}:
        value = (0., -.6, -.7, -.9, -.5, -1.8, -1.3, -.1)[context]
        if root == 'degree' and p in {'high', 'higher'}:
            value = -3.
    elif root in {'type', 'kind', 'sort'}:
        value = (0., -.6, -1.5, -3.2, -.2, -.7, -2.8, -1.)[context]
        if p == 'the':
            value = -.05 if root == 'kind' else -.85
    elif root == 'range':
        value = (0., -.1, -1.3, -.6, -.2, -1.3, -2.5, -.2)[context]
        if p in {'wide', 'wider', 'broad', 'broader', 'diverse', 'full'}:
            value = -3.7
        if p in {'maximum', 'minimum', 'high', 'low', 'total'}:
            value = -.2
    elif root == 'sense':
        value = (-.3, -.2, -3., -.1, -2.3, -2.5, -.2, -.2)[context]
        if before == 'in' and p in ARTICLES:
            value = .3
    elif root == 'lack':
        value = (-1., -2.1, -2.8, -2.6, -3., -2., -2., -1.)[context]
    elif root == 'lot':
        value = -.5 if p in {'a', 'whole'} else -.1
    else:
        strength = STRENGTH[root]
        factor = (.02, .2, 1., .6, .3, .9, .7, .6)[context]
        value = -strength * factor
    # Carry a determiner through adjectives, rather than treating a noun
    # compound ('television series', 'data set') as a partitive phrase.
    determiner = ''
    for word in reversed(history[-5:]):
        if word in DETERMINERS:
            determiner = word
            break
        if not (adjective(word) or word.endswith('ly') or
                word in {'own', 'more', 'most', 'very'}):
            break
    if context == 0 and determiner:
        value -= .7
    if p not in DETERMINERS and determiner:
        if root in {'set', 'collection', 'series'}:
            value = -3.7 if determiner in {'a', 'an'} else -1.4
        elif root in {'list', 'array', 'sequence'}:
            value = -2. if determiner in {'a', 'an'} else -1.
    if plural and context == 0:
        value -= .3
    if s.strip()[:1].isupper():
        value *= .7
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    history = re.findall(r"[A-Za-z]+|['’]s|[^\w\s]", tail.lower())[-5:]
    p = history[-1] if history else ''
    before = history[-2] if len(history) > 1 else ''
    embedded = tail and s and tail[-1].isalnum() and s[0].isalnum()
    value = 0. if embedded else predict(s, p, before, history)
    return (doc, (tail + s)[-100:]), float(value)

programs.haiku:
"""Quantity nouns that head a partitive "X of ..." phrase ("a series of", "a number of",
"a lack of", "a wide range of").

The component is negative on that noun, the word just before the "of". It is strongest
right after an opener such as "a", "this" or "wide", weaker after "the", and near zero in
code or after punctuation. Its activation is mildly positive on the first word of a new
document (the word after <|endoftext|>), which is a small, separate effect.
"""

READS = ()

# Nouns almost always used as "a <noun> of ...": strongest.
QUANTITY_STRONG = {
    "series", "type", "types", "set", "sets", "kind", "kinds", "sort", "sorts", "sense", "range",
    "collection", "lack", "pair", "pairs", "plethora", "myriad", "multitude", "barrage",
}
# Other quantity, collective and measure nouns: medium.
QUANTITY_MEDIUM = {
    "number", "numbers", "amount", "amounts", "variety", "mix", "group", "groups", "degree",
    "list", "piece", "pieces", "sequence", "bunch", "member", "members", "instance", "instances",
    "forms", "subset", "tipo", "tipos", "serie", "numero", "número", "lista", "liste",
}
# Weaker relational nouns and "wide/large"-type openers: small.
WEAK_NOUNS = {
    "array", "combination", "combinations", "copy", "copies", "increase", "source", "sources",
    "level", "levels", "network", "mixture", "form", "version", "versions", "lot", "lots",
    "blend", "choice", "understanding", "means", "host", "wide", "large", "broad", "diverse",
    "vast", "huge", "great", "limited",
}
# Words that open a noun phrase: "a", "this", "any", "some", "wide", ...
OPENERS = {
    "a", "an", "this", "these", "any", "some", "other", "certain", "different", "same", "total",
    "maximum", "minimum", "wide", "large", "vast", "broad", "diverse", "huge", "great", "high",
    "small", "full", "several", "many", "two", "three", "each", "every", "all", "both",
    "another", "various", "particular", "specific", "what", "such", "one",
}
DOC_START_OFFSET = 0.3  # mild positive value on the first word after <|endoftext|>


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0
    word = prefix.token_strings[-1].strip().lower()
    prev_raw = prefix.token_strings[-2]
    if prev_raw == "<|endoftext|>":
        return carry, DOC_START_OFFSET
    if word in QUANTITY_STRONG:
        size = 2.5
    elif word in QUANTITY_MEDIUM:
        size = 1.5
    elif word in WEAK_NOUNS:
        size = 0.8
    else:
        return carry, 0.0
    prev = prev_raw.strip().lower()
    if prev in OPENERS:
        ctx = 1.0          # "a series", "wide range": the noun opens a phrase
    elif prev == "the":
        ctx = 0.35
    elif prev.isalpha():
        ctx = 0.1          # "data set", "user type": a compound, not a partitive
    else:
        ctx = 0.03         # punctuation or code, e.g. "(set" or "= number"
    return carry, -size * ctx

programs.sol:
"""Approximate the dominant first-person proposal/future pattern.

Respond on me/us in 'let me/us', 's in 'let's', and will/shall/'ll after
I/we. Capitals, punctuation and nearby function words adjust the strength;
'please', pronouns and auxiliaries before 'let' reduce its response.
Also recognize 'let's not', informal 'Lets', and whole-token Chinese
让我/让我们 ('let me/us'). Other tokens get zero, except a small negative
bias at document starts. These local rules do not model irregular responses.
"""

READS = ()
SUBORDINATORS = {'that', 'which', 'who', 'when', 'if', 'as', 'whether'}
PERSONAL_PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}
PERMISSION_CONTEXT = {
    'to', 'not', 'never', 'have', 'has', 'had', 'will', 'would',
    'can', 'could', 'may', 'might', 'must', "'t", "n't",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, earlier = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1].replace('’', "'")
    word, before, prior = token.strip(), previous.strip(), earlier.strip().lower()
    value = -0.13 if first else 0.0
    boundary = (not earlier or not earlier[-1:].isalpha()
                or previous[:1].isspace()
                or earlier.endswith(('\\n', '\\r')))

    if boundary and before.lower() == 'let':
        if word in {'me', 'us'}:
            value = 1.49 if before == 'Let' else 1.30
            if prior == 'please':
                value = 0.72
            elif prior in PERMISSION_CONTEXT or prior in PERSONAL_PRONOUNS:
                value = 0.20
            elif prior in {'but', 'wait'}:
                value += 0.20
        elif word == "'s":
            value = 0.99 if before == 'Let' else 0.87
    elif word == 'Lets' and before.lower() not in PERSONAL_PRONOUNS:
        value = 0.85
    elif word == 'not' and before == "'s" and prior == 'let':
        value = 0.60
    elif word in {'让我', '让我们'}:
        value = 0.90
    elif boundary and before in {'I', 'i', 'we', 'We'}:
        if word in {'will', 'shall', "'ll"}:
            singular = before.lower() == 'i'
            value = 0.90 if singular else 0.60
            if word == "'ll" and singular:
                value += 0.10
            if before == 'We':
                value = 0.87
            if prior in SUBORDINATORS:
                value -= 0.40 if singular else 0.30
            elif prior in {'and', 'or'}:
                value -= 0.18
            elif singular and (any(c in earlier for c in '.,!?\n')
                               or earlier.endswith(('\\n', '\\r'))
                               or prior in {'so', 'but', 'now'}):
                value += 0.25
            if singular and previous == 'I':
                value += 0.15
            if word == 'shall':
                value += 0.35

    return (doc, token, previous), value

programs.haiku:
"""Announces an action the writer is about to take, on the word just before the verb.

The component fires on the object or modal of a "let's / let me / let us" or
"I will / I'll / we will / we shall" construction, at the word right before the
verb: the "me" of "Let me check", the "'s" of "let's", the "us" of "let us", the
"will" or "'ll" of "I'll try" or "we will see". Typical sizes, in the model's own
units: "Let me" about 1.45 (the strongest, as in agent-style reasoning), "let us"
1.2, "I'll" 1.0, "I will" 0.9, "let's" 0.9, "we will" and "we'll" about 0.6.
Everything else is 0: "tell me", "for me", "you will", "it will", "I am" and
"I have" are all silent.

The program looks only at the current word and the one before it, and it does
not look across a document boundary.
"""

READS = ()

# the word just before, mapped to the value of the word that follows it
AFTER_LET = {"me": 1.45, "'s": 0.9, "’s": 0.9, "us": 1.2}
AFTER_I = {"will": 0.9, "'ll": 1.0, "’ll": 1.0, "shall": 1.0}
AFTER_WE = {"will": 0.65, "'ll": 0.6, "’ll": 0.6, "shall": 0.65}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = len(toks) - 1
    cur = _word(toks[t])
    same_doc = t >= 1 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    prev = _word(toks[t - 1]) if same_doc else ""
    value = 0.0
    if prev == "let":
        value = AFTER_LET.get(cur, 0.0)
    elif prev == "i":
        value = AFTER_I.get(cur, 0.0)
    elif prev == "we":
        value = AFTER_WE.get(cur, 0.0)
    return carry, float(value)

programs.sol:
"""Approximate a sparse web/forum/log-formatting response.

The largest estimates mark quotation headings, profile fields and familiar
page or log boilerplate. Some link/reference markers have negative signs.
Ordinary text gets a small baseline; document-initial tokens get coarse
case/character-type corrections, not fine lexical variation.
Only the last 800 decoded characters are retained, resetting per document.
"""
import re

READS = ()

# Colons completing human-readable fields, rather than code or clock times.
LABELS = {
    'Output': 1.4, 'Input': 0.7, 'Answer': 0.65,
    'Location': 0.7, 'Status': 0.7,
    'Title': 0.5, 'Re': 0.5,
    'Quote': 0.85, 'Score': 0.85, 'Response': 0.85,
    'Description': 0.45, 'Explanation': 0.45,
    'Topic': 0.45, 'Citation': 0.45,
    'Result': 0.3, 'Source': 0.3, 'Usage': 0.3,
    'Date': 0.2, 'Name': 0.2, 'Author': 0.2,
    'Category': 0.2, 'Size': 0.2, 'Stage': 0.2,
}
# Recognizable template endings, not tokenizer IDs or arbitrary vocabulary.
MARKERS = (
    ('RT @', -4.3), ('arXiv', -1.65),
    ('Official website', -1.6), ('Encyclopedia of', -0.65),
    ('GMAT Club', -1.4), ('Latest reply', -2.3),
    ('Downloaded', 0.71), ('Downloaded from', 0.8),
    ('Rate this', 0.7), ('IP Logged', 1.45), ('BOOKMARKED', 2.3),
