            return 1.45
        if re.search(r'\b\w*Warning:$', tail):
            return -2.0 if position < 3 else -0.7
        if re.search(r'(?:^|\n)Forum:$', tail):
            return -1.95
        if re.search(r'(?:given|Given):$', tail) and 'Kudos' in before:
            return 0.55
        if re.search(r'(?:Liked|Likes Given):$', tail):
            return 0.85
        label = re.search(r'([A-Za-z]+)\s*:$', tail)
        if label and label[1] in LABELS:
            return LABELS[label[1]]
