Cur/kur fragments, recursion, curing and curling usually give a negative
response; a few neighboring hard-c/k spellings give a positive one. Common
whole words such as current and secure are weak. Remember two tokens to join
split spellings, including Cyrillic ones, and reset at document boundaries.
There is also a fixed negative exception for a leading-space article at the
first position. These rules approximate, rather than exhaust, the response.
"""
import re
import regex
from anyascii import anyascii

READS = ()


def spelling(s):
    if regex.search(r'\p{Script=Cyrillic}', s):
        s = anyascii(s)
    return s.lower()


def response(raw, previous, older, first):
    t = spelling(raw)
    p = spelling(previous)
    if previous[:1].isalpha():
        p = spelling(older) + p
    w = t.strip(' \n\t_.,:;!?()[]{}<>/\\\"\'-')
