        return -1.066
    if re.search('cur|kur', t):
        if re.search(
            r's[eé]cur|accur|occur|currenc(?:y|ies)|mercury|obscur|sakura', t
        ):
            return 0.0
        if 'current' in t:
            if 'concurrent' in p + t:
                return -1.1
            return -0.8 if 'recurrent' in p + t else -0.17
        if re.search(r'curric|curat(?:e|or|ion)|curtain|curtis', t):
            return -0.4
        if 'curved' in t:
            return 1.3
        if 'curvature' in t:
            return -1.2
        if re.search(r'curves?$', w):
            return -0.1
        if 'curious' in t or 'curiosity' in t or 'curly' in t:
            return -1.0
        if 'recursiv' in t:
            return -4.4 if raw[:1].isspace() else -2.5
        if 'cured' in t:
            return -2.2
        if w == 'curl':
            return -4.1
        if w == 'cur':
            return -3.5 if raw[:1].isspace() or raw[:1].isupper() else -6.5
        if w == 'kur':
            return -3.1 if raw[:1].isspace() else -4.0
        if re.search(r'recur|precurs|incur|procure|cur(?:e|ing|ry|se|s$|l)', t):
            return -3.4
        return -2.0
    if not t[:1].isalpha():
        return 0.0
