            r'secur(?:e|it|ing)|accura|occurr|currenc(?:y|ies)|obscur', p + t
        ):
            return 0.0
        if t.startswith('url') and p.endswith('k'):
            return 0.0
        if t.startswith(('urrent', 'urv')):
            return -0.5
        return -5.1
    if not raw[:1].islower():
        return 0.0
    if p.endswith(('cur', 'kur', 'curs', 'kurs', 'curr', 'kurr')):
        if t.startswith('v'):
            return 0.6
        if t.startswith('ial'):
            return -5.8
        return -3.7 if t.startswith(('se', 'ative', 'ios')) else -2.0
    if p.endswith(('c', 'k')):
        if t.startswith('ug'):
            return 4.5
        if t.startswith(('ible', 'ice', 'order')):
            return 1.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, older = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, older, first)
    return (doc, token, previous), value

