"""layers.1.mlp.down_proj:5430 -- a sparse, mostly-quiet component.

Its activation is near 0 on most tokens. It moves in a few concept-level ways:

* Start of a document (first token of a row or of a packed document, where
  attention resets): clearly positive, about +0.24.
* Markdown bold markers ("**") in running text: strongly negative, about -1.6
  for " **" and -0.2 for a bare "**".
* Link and URL markup ("](", ".md", "https", "http", "://"): negative, about -0.3.
* Typeset/markup words ("bf", "tt", "boxed"): negative, about -0.5.
* A bare space token right after a period: mildly negative, about -0.17.
* Dot leaders ("··", as in a table of contents): positive, about +0.34.
* Programming keywords (return, null, void, def, fn, ...): mildly positive, +0.06.

Everything else predicts 0. The program is stateless: it reads only the newest
token and whether the document id just changed.
"""

READS = ()

BOLD = {" **": -1.6, "**": -0.2, " (**": -1.2}
LINK_MARKUP = {"](", ".md", "https", " https", "http", "://"}
TYPESET = {"bf", "tt", "boxed"}
DOT_LEADER = {"··"}
CODE_WORDS = {"return", "null", "void", "def", "fn", "command", "param", "static",
              "invalid", "valid", "try", "package", "self", "function", "class", "import",
              "const", "let", "var", "new", "None", "true", "false", "nil"}
DOC_START = 0.24


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    t = prefix.position
    doc_start = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    prev = prefix.token_strings[-2] if t > 0 else ""
    if doc_start:
        return carry, DOC_START
    if tok in BOLD:
        return carry, BOLD[tok]
    if tok in LINK_MARKUP:
        return carry, -0.3
    if tok in TYPESET:
        return carry, -0.5
    if tok in DOT_LEADER:
        return carry, 0.34
    if tok == " " and prev == ".":
        return carry, -0.17
    if tok.strip() in CODE_WORDS or (tok.startswith(" ") and tok[1:] in CODE_WORDS):
        return carry, 0.06
    return carry, 0.0

