letter continuations and middle-dot leaders. Unrecognized contexts return zero.
Amplitudes are approximate training measurements, not grammatical truth values.
"""
READS = ()
ONE = {
    'each': 6.4, 'either': 6.5, 'which': 5.1, 'every': 4.4,
    'single': 2.7, 'other': 2.5, 'another': 2.3, 'any': 1.7,
    'some': 0.95, 'this': 0.95, 'that': 0.3, 'no': 0.2,
    'first': 0.8, 'second': 1.2, 'third': 1.2, 'last': 0.9,
}
SIDE = {
    'either': 6.8, 'neither': 4.5, 'which': 3.9, 'each': 3.8,
    'one': 3.7, 'both': 3.5, 'other': 3.2, 'opposite': 1.9,
    'this': 1.7, 'same': 1.5, 'another': 1.3, 'that': 1.2,
    'left': 0.45, 'right': 0.45,
}
NEGATION = {
    'don': -.32, 'doesn': -.28, 'didn': -.22, 'isn': -.56,
    'wasn': -.44, 'aren': -.65, 'weren': -.4, 'haven': -.75,
    'hasn': -.4, 'hadn': -.4, 'couldn': -.3, 'wouldn': -.34,
    'shouldn': -.28, 'mustn': -.4, 'needn': -.5, 'won': -.2,
