PHRASES = {
    'one another': -3.0, 'whether or': -5.1, 'either or': -4.1,
    'one or': -.44, 'either of': -2.1, 'either way': -4.3,
    'which way': -2.6, 'one way': -.75,
    'just over': -3.6, 'just under': -3.6,
}


def selected_head(word, selector):
    if word == 'one':
        return -ONE.get(selector, 0.0)
    if word in {'side', 'end', 'direction'}:
        scale = {'side': 1.0, 'end': .7, 'direction': .6}[word]
        return -scale * SIDE.get(selector, 0.0)
    if word in {'sides', 'ends'}:
        return -{'both': 5.2, 'all': 2.4, 'opposite': 1.5,
                 'other': .7}.get(selector, 0.0)
    if word in {'kind', 'sort', 'type'}:
        if selector in {'some', 'any', 'what'}:
            return {'kind': -3.25, 'sort': -3.0, 'type': -3.8}[word]
        if selector in {'this', 'that'}:
            return (-3.2 if word == 'type' else -1.5)
        if selector in {'other', 'each', 'every', 'either', 'neither'}:
            return -2.0 if word == 'type' else -1.5
        if selector in {'same', 'different', 'certain', 'another', 'one'}:
            return -1.2 if word == 'type' else -.5
    if selector == 'all':
        return -{'kinds': 5.7, 'sorts': 5.7, 'types': 2.7,
                 'levels': 4.7, 'manner': 4.8}.get(word, 0.0)
    if word in {'kinds', 'sorts', 'types'}:
        if selector in {'these', 'those'}:
            return -2.3 if word == 'types' else -3.0
        if selector in {'different', 'various', 'certain', 'many', 'several'}:
            return -.9
        if selector in {'other', 'both', 'what', 'which'}:
            return -1.7
    return 0.0


def local_value(raw, history):
    word = raw.strip().lower()
    p = history[-1].strip().lower() if history else ''
    q = history[-2].strip().lower() if len(history) > 1 else ''
    if raw in {'n', 'N', 'nt'} and p in AUX:
        if raw != 'N' or history[-1].strip().isupper():
            if raw == 'nt':
                return -2.0
            return -10.7 if history[-1].strip()[:1].isupper() else -5.0
    if len(word) >= 2 and set(word) == {'·'}:
        return -3.0
    if history and not (raw[:1].isspace() or not history[-1][-1:].isalnum()):
        if raw in {'n', 'on', 'н', 'он'}:
            if p[-1:] in {'d', 'д'}:
                return -1.4 if raw in {'n', 'н'} else -2.0
            if raw == 'on':
                return {'h': -1.0, 'n': .7}.get(p[-1:], 0.0)
        return -2.0 if (raw, p) in {('/she', 'he'), ('/her', 'his')} else 0.0
    if word in NEGATION:
        value = NEGATION[word] * (1.4 if p == 'i' else 1.0)
        if word == 'won' and p in {'has', 'have', 'had', 'he', 'she'}:
            return 0.0
        return value * (3.0 if raw.strip().isupper() else 1.0)
    if word == 'kind' and p == 'a':
        unique = (q == 'of' and len(history) >= 3
                  and history[-3].strip().lower() == 'one')
        return 6.5 if unique else 1.3
    if p + ' ' + word in PHRASES:
        return PHRASES[p + ' ' + word]
    if word == 'of':
        if p == 'side':
