                     'inner', 'outer', '-hand'}:
                return -1.6
            return min(-.2, 1.25 * selected_head(p, q))
        if p == 'sides':
            return -{'both': 5.3, 'all': 3.1, 'two': 1.5}.get(q, 0.0)
        if p == 'end':
            return .5 * selected_head(p, q)
        factor = {'this': 1.0, 'that': .6, 'these': 1.0, 'those': 1.0,
                  'any': .4, 'some': .23, 'what': .12,
                  'all': .4, 'each': .9, 'every': 1.0}.get(q, .65)
        if p == 'type' and q == 'this':
            factor = .8
        if p in {'kind', 'sort', 'type', 'kinds', 'sorts', 'types'}:
            return factor * selected_head(p, q)
        return 0.0
    value = selected_head(word, p)
    return value * (.7 if raw.strip().isupper() else 1.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    value = local_value(raw, history)
    return (doc, (history + (raw,))[-3:]), float(value)

