"""A signed spelling-fragment detector, not a subject-matter detector.

Look for i (or y) followed by c/k/q, including across token boundaries.
Short fragments after r are positive; after t (including th) negative.
V/w/k fragments are also positive. Long, integrated word pieces are much
weaker, and 'ich' is weaker than 'ic'; -ick pieces persist longer.
Greek ti+k fragments get an extra negative response. Transliteration extends the
same rules to other scripts. A short continuation can retain some signal
for one token. All state resets at document boundaries.
"""
from functools import lru_cache
import regex as re
from anyascii import anyascii

READS = ()
IC = re.compile(r'i[ckq]')
GREEK = re.compile(r'\p{Script=Greek}')


@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower().replace('y', 'i')


def fragment_value(letter, token, offset, after, ch_spelling):
    length = len(token.strip())
    hard_ending = token.endswith(('ic', 'ik', 'ick', 'iq'))
    if letter == 'r':
        if length <= 3:
            if hard_ending:
                return 2.65
            return 0.66 if ch_spelling else 1.49
        if length <= 4:
            if ch_spelling:
                return 0.06
            return 1.30 if token.startswith('i') else 0.72
        return 0.07
    if letter == 't':
        if length <= 4:
            if after > 1:
                return -0.35
            if length <= 2:
                return -1.64
            return -0.95 if token.startswith('i') else -1.39
        if offset <= 2:
            return -0.85 if after <= 1 else -0.32
        return 0.03
    if length <= 3:
        if letter in 'vwkc':
            if hard_ending:
                return 0.57 if letter == 'c' else 1.99
            return 0.46
        return 0.21 if offset < 0 else 0.07
    return 0.02


def continuation_value(letter, previous, token):
    if letter == 'r':
        if len(previous) <= 3:
            return 1.30
        return 0.37 if len(token) <= 3 else 0.08
    if letter == 'v':
        return 0.62
    if len(token) <= 3:
        if token.startswith('u'):
            return 0.43
        return 0.0 if letter == 't' else 0.17
    return 0.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, previous_letter = '', '', None
    else:
        _, tail, previous, previous_letter = carry
    raw = prefix.token_strings[-1]
    token = spelling(raw)
    joined = tail + token
    boundary = len(tail)
    match = next((m for m in IC.finditer(joined)
                  if m.end() > boundary), None)
    letter = None
    value = 0.0
    if match is not None:
        start = match.start()
        letter = joined[start - 1:start] or ' '
        if joined[max(0, start - 2):start] == 'th':
            letter = 't'
        value = fragment_value(
            letter, token, start - boundary, len(joined) - match.end(),
            'ich' in previous + token)
        # Greek ti+k fragments have a stronger negative response.
        offset = start - boundary
        if (letter == 't' and offset <= 2
                and len(token.strip()) <= 5 and GREEK.search(raw)):
            value -= 1.0
