        if (letter in 'rvwku' and 'ick' in joined[start:]
                and offset <= 2 and len(token.strip()) <= 7
                and not token[:1].isspace()):
            value += 0.7
    elif (previous_letter is not None
          and previous.endswith(('ic', 'ik', 'iq', 'ick'))
          and token.isalpha() and len(token) < 10):
        value = continuation_value(previous_letter, previous, token)
        if (previous_letter == 'r' and len(previous) <= 3
                and token.startswith('u')):
