      'make': 3.3, 'get': 2.8, 'catch': 3.3, 'hold': 2.8,
      'show': 1.5, 'bring': 1.8, 'wake': 1.2, 'pick': 1.2,
      'let': 1.2, 'stay': 1.2, 'throw': 1.8, 'talk': 1.8}
QUANTITY = {'large', 'small', 'huge', 'limited', 'considerable', 'greater',
            'enough', 'finite', 'infinite', 'any', 'different'}


def phrase(word, prev, earlier):
    base = 'have' if prev in {"'ve", '’ve'} else verb(prev)
    if word == 'up':
        if prev == 'grew':
            return 4.9
        if prev == 'grown':
            return 2.7
        if prev == 'made':
            return 0.6
        if prev == 'shown':
            return 3.0
        return UP.get(base, 0.08)
    if word == 'care' and base == 'take':
        return -5.3 if prev == 'taken' else -4.4 if prev == 'took' else -3.7
    if word == 'use':
        return -6.0 if base == 'make' else -2.3 if prev == 'best' else 0.08
    if word == 'hold':
        if base in {'get', 'take', 'seize'} or (prev == 'a' and verb(earlier) == 'get'):
            return -6.6
        return -3.7 if base == 'have' else 0.0
    if word == 'track' and base in {'keep', 'lose'}:
        return -5.2
    if word == 'sight' and base == 'lose':
        return -4.0
    if word in {'advantage', 'possession', 'control'} and base == 'take':
        return -3.1 if word == 'advantage' else -2.0
    if word == 'over':
        return (3.2 if prev == 'took' else 2.4) if base == 'take' else -0.08
    if word == 'look':
        return -2.8 if prev == 'a' else 0.1
    if word in {'ever', 'never', 'always'} and base == 'have':
        return {'ever': 2.2, 'never': 1.7, 'always': 0.6}[word]
    if word in {'got', 'gotten'}:
        if base == 'have':
            return -3.3 if prev in {'has', 'had'} else -1.3
        if verb(earlier) == 'have' and 'adverb' in wordnet.parts_of_speech(prev):
            return -2.5
    if word == 'even' and prev in {'not', "n't", "'t", '’t', 'without'}:
        return 1.1
    if word == 'idea':
        return 1.7 if prev == 'no' else -1.9 if prev == 'good' else 0.0
    if word == 'trouble' and (base == 'have' or prev == 'some'):
        return 2.3
    if word in {'too', 'rid'} and base == 'get':
        return -1.8
    if word == 'luck' and prev == 'good':
        return 2.0
    if word == 'see':
        return -0.8 if prev in {"'s", '’s'} else -0.4 if prev == 'me' else 0.0
    if word.endswith(('self', 'selves')) and base in {'have', 'give', 'lose', 'find'}:
        return -2.1 if base != 'find' else -1.0
    if word == 'number':
        if prev == 'the':
            return 0.22
        return -0.5 if prev == 'a' else -1.3 if prev in QUANTITY else 0.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous, earlier = carry[1:3] if same_doc else ('', '')
    position = carry[3] + 1 if same_doc else 0
    word, prev = token.strip().lower(), previous.strip().lower()
    value = phrase(word, prev, earlier.strip().lower()) if token[:1].isspace() else 0.0
    if word == 'grep':
        value = 2.7
    elif word == 'rep' and prev == 'pg':  # pgrep, process-search command
        value = 6.0
    # Technical names with a separately tokenized initial G.
    if previous.rstrip().endswith(('G', 'g')) and not token[:1].isspace():
        if word == 'pt':  # GPT; SGPT has a weaker response
            value = 2.2 if prev == 'sg' else 4.4
        elif word == 'pp':  # 3GPP
            value = 5.0
        elif word == 'str':  # GST return forms
            value = -3.6
        elif word == 'cc':  # GCC compiler
            value = 2.5
        elif word == 'fp':  # GFP protein
            value = 1.0
        elif word == 'op':  # gopkg package paths
            value = -1.5
    if prev in {'g', 'h'} and not token[:1].isspace() and word.startswith('i'):
        value = -4.5 if word == 'ie' else -0.6
    if position == 1 and previous == 'Title' and token == ':':
        value = 5.85
    return (doc, token, previous, position), value

programs.haiku:
"""layers.1.mlp.down_proj:5435 -- a 'phrasal verb / light-verb idiom' detector.

The component is quiet almost everywhere (typical size ~0.03). It switches on at the
second word of a short verb idiom, with a sign that depends on the idiom:

* Positive on the particle "up" (or "over") completing a phrasal verb:
  "keep up", "give up", "grow up" (strongest, ~+6); "take up", "make up", "catch up"
  (~+3.5); "pick up", "wake up", "show up", "bring up" (~+1.5). "set up", "end up" and
  "sign up" stay near 0.
* Negative on the object noun of a light-verb idiom that is followed by "of":
  "take care of", "keep track of", "make use of", "take advantage of", "take control of",
  "lose sight of", "get hold of", "take a look at" (about -4 to -5).
* Small fixed responses: "grep" (shell command, +3), "GPT" split as "G" + "PT" (+4),
  "have ever/never" (+2), "have got" (-2), and the token "··" (+0.9).

Everything else predicts 0. The program looks only at the current and the two previous
tokens, and it resets at a document boundary.
"""
READS = ()

# Verbs that take the particle "up" (or "over") as a phrasal verb.
UP_STRONG = {"keep", "kept", "keeping", "give", "gave", "giving", "given",
             "grow", "grew", "grown", "growing"}
UP_MEDIUM = {"take", "took", "taken", "taking", "takes", "make", "makes", "making",
             "catch", "caught", "hold", "holds", "hang", "hung", "hanging"}
UP_WEAK = {"pick", "picked", "picks", "picking", "wake", "woke", "woken", "waking",
           "wakes", "show", "showed", "shows", "showing", "bring", "brings", "brought",
           "bringing", "get", "got", "gets", "getting", "made"}

# Light verbs whose object noun is typically followed by "of".
LIGHT_VERBS = {"take", "took", "taken", "taking", "takes", "keep", "kept", "keeping",
               "keeps", "make", "made", "making", "makes", "lose", "losing", "lost",
               "give", "gave", "given", "get", "got", "getting", "gets"}
IDIOM_NOUNS = {"care", "track", "use", "advantage", "control", "charge", "note", "sight",
               "possession", "account", "hold", "look", "glimpse", "grip", "notice", "stock"}
HAVE = {"have", "has", "had", "'ve"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    n = len(prefix.token_ids)
    same = n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same else ""
    prev2 = prefix.token_strings[-3].strip().lower() if same and n > 2 else ""

    if word in {"up", "over"}:
        if prev in UP_STRONG:
            return carry, 6.0
        if prev in UP_MEDIUM:
            return carry, 3.5
        if prev in UP_WEAK:
            return carry, 1.5
    if word in IDIOM_NOUNS and prev in LIGHT_VERBS:
        return carry, -5.0
    if word in {"look", "hold", "glimpse", "grip", "sight"} and prev == "a":
        if prev2 in LIGHT_VERBS or prev2 in HAVE:
            return carry, -4.0
    if word in {"ever", "never"} and prev in HAVE:
        return carry, 2.0
    if word == "got" and prev in HAVE:
        return carry, -2.0
    if word == "grep":
        return carry, 3.0
    if word == "pt" and prev == "g":
        return carry, 4.0
    if word == "··":
        return carry, 0.9
    return carry, 0.0

programs.sol:
"""A token-spelling detector centered on m-initial size and degree words.

Recognize main/major/minor/mini, Romance more/less/better comparatives, and
weaker may/maybe spellings and split diphthongs after m. Track the current
word so a comparative completed across tokens can fire too. Short
comparative endings and clipped roots
are especially strong.
A path's main entry, the .mjs extension, and an opening Title: colon are
separate formatting cases. Unrecognized text receives zero.
"""
import re
from anyascii import anyascii

READS = ()
# English size/prominence words and Romance comparative stems.
DEGREE = {
    'main': 1.0,
    'mains': 3.7,
    'major': 2.0,
    'maj': 2.0,
    'mej': 5.5,
    'minor': 2.7,
    'mini': 1.4,
    # More / less / greater (Romance languages).
    'mai': 3.0,
    'mais': 0.9,
    'más': 0.75,
    'menos': 1.8,
    'menor': 6.0,
    'maior': 4.5,
    'mayor': 3.2,
    # Better (Spanish, Portuguese, Italian, French).
    'mejor': 3.4,
    'melhor': 3.8,
    'miglior': 3.8,
    'maggior': 4.0,
    'meglio': 4.2,
    'meilleur': 2.0,
    'mieux': 1.7,
    'moins': 0.6,  # French: less
    'migliori': 1.7,
}
COMPARATIVES = {
    'major', 'minor', 'menor', 'maior', 'mayor',
    'mejor', 'melhor', 'miglior', 'maggior',
}
ENDINGS = ('es', 's', 'e', 'i')


def degree(word):
    if word in DEGREE:
        return DEGREE[word], word
    for ending in ENDINGS:
        if word.endswith(ending):
            root = word[:-len(ending)]
            if root in COMPARATIVES:
                return DEGREE[root], root
    return 0.0, ''


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, tail = '', '', ''
    else:
        _, previous, before, tail = carry
    lower = token.lower()
    attached = bool(lower and lower[0].isalpha() and tail)
    key = lower.lstrip(' ./_(-')
    word = tail + lower if attached else key
    match = re.search(r'[^\W\d_]+$', word)
    new_tail = match.group()[-24:] if match else ''
    value, root = degree(key)
    if key == 'main':
        if token.startswith(('/', '.')):
            value = 2.8
        elif token.startswith('_'):
            value = 0.7
        elif token.strip().startswith('Main'):
            value = 1.4
        elif attached:
            value = 2.5
        elif not token.startswith(' '):
            value = 1.4
    elif key == 'mai' and 'M' in token:
        value = 4.5
    elif key in ('major', 'minor') and token[0].isalpha():
        value *= 1.45
    elif key == 'major' and 'M' in token:
        value = 2.9
    if key == 'maybe':
        value = 0.65
    elif key == 'may':
        value = 0.3 if 'M' in token else 0.11
        if not token.startswith(' '):
            value = 1.1
    if attached and 'm' in tail:
        stem = word[word.rfind('m'):]
        base, root = degree(stem)
        if base:
            scale = 1.4 if root in COMPARATIVES else 1.1
            value = max(value, base * scale)
            if root in COMPARATIVES and lower in ('or', 'ors'):
                value = base + 3.5
            elif root in COMPARATIVES and lower in (
                'ore', 'ori', 'ores', 'iores', 'i'
            ):
                value = base + 1.5
            elif root in COMPARATIVES and lower == 'ior':
                value = base + 0.5
            if root == 'maggior' and lower == 'i':
                value = 2.7
        if stem == 'maj':
            value = 4.5
        elif stem == 'maggi':  # clipped Italian maggiore (greater)
            value = 8.5
        elif stem == 'magn':  # Latin magn- (large/great)
            value = 2.3
        if stem == 'maybe':
            value = 2.1
        if stem == 'maint' and token.isupper():
            value = 3.7
    # A split diphthong after the letter m, including Cyrillic м.
    if attached and tail.endswith(('m', 'м')):
        sound = anyascii(lower)
        if sound == 'ai':
            value = 3.2 if tail.endswith('м') else 4.5
        elif sound in ('ei', 'ey', 'ay'):
            value = 2.0
    if token == 'js' and previous.endswith('.m'):
        value = 2.4
    if token == ':' and previous == 'Title' and before in ('', '<|endoftext|>'):
        value = 25.58
    return (doc, token, previous, new_tail), value

"""Sparse surface-pattern approximation, mainly at document openings.

An initial 'Title:' has a large negative pulse on its colon. The greeting
'Hello' and a space-prefixed period are positive openings; a // comment
header is negative. Repeated middle dots are positive, and mixed-width
question-mark/punctuation sequences are negative. Chat boundary markers
have a small positive baseline. Other opening tokens get a weak negative
baseline, stronger for English articles. Ordinary unmatched text is zero.
These are separate observed motifs, not a single semantic category.
"""
READS = ()
CHAT_MARKERS = frozenset(('<|im_start|>', '<|im_end|>', '</tool_call>'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
        position += 1

    value = 0.0
    if position == 0:
        value = -0.10
        if token == 'Title':
            value = 0.43
        elif token == 'Hello':
            value = 1.83
        elif token == '//\n':
            value = -2.62
        elif token == ' .':
            value = 2.93
        elif token in ('The', 'A', 'An'):
            value = -0.43
    elif position == 1:
        if previous == 'Title' and token == ':':
            value = -11.77
        elif previous == '//\n' and token == '//':
            value = 0.59

    if token in CHAT_MARKERS:
        value = 0.11 if position == 0 else 0.057
    elif token == '··' and (position == 0 or previous == '··'):
        value = 2.73
    elif previous == '?' and token in ('；', '！', '？'):
        value = -0.85

    return (doc, position, token), value
